INSERT INTO `autores` (`id`, `nome`, `biografia`, `escola_literaria`, `capa`) VALUES
(1, 'Pero Vaz de Caminha', 'Pero Vaz de Caminha nasceu por volta de 1450 no Porto, Portugal. Seu pai era Cavaleiro do Duque de Bragança. Foi mestre da balança da Casa da Moeda, ocupando o cargo de escrivão e tesoureiro. Além de escrivão, foi vereador da cidade do Porto, em 1497. Casou-se com Dona Catarina e com ela teve uma filha: Isabel de Caminha. Em março de 1500, acompanhou a frota de Pedro Álvares Cabral como escrivão-mor. Quando chegaram ao Brasil em 22 de abril de 1500, ele escreveu um documento relatando para o Rei Dom Manuel I as impressões das terras encontradas. Esse relato ficou conhecido como "A Carta de Pero Vaz de Caminha". Ao deixarem o Brasil, seguem rumo às Índias, onde morre numa batalha nas feitorias portuguesas que já estavam instaladas em Calicute. Faleceu com 50 anos, em Calicute, Índia, em 15 de dezembro de 1500.', 'Quinhentismo', '../obras/autores/perovaz.jpeg'),
(2, 'Hans Staden', 'Hans Staden (1525-1576) foi um aventureiro e comerciante de armas alemão. Aportou nas costas do recém-descoberto Brasil. Deixou interessantes observações sobre a vida e os costumes dos indígenas brasileiros. Hans Staden nasceu em Homberg, Alemanha, no ano de 1525. Nessa época, a Coroa portuguesa tentava colonizar o Brasil, visando garantir sua posse e defende-la dos piratas e comerciantes franceses. A capitania de Pernambuco havia sido entregue ao donatário Duarte Coelho, em 1534, que fundou a futura vila de Olinda e mais tarde o primeiro engenho de Pernambuco, Nossa Senhora da Ajuda, mais tarde chamado Forno da Cal.', 'Quinhentismo', '../obras/autores/hansstaden.jpg'),
(3, 'José de Anchieta', 'José de Anchieta (1534-1597) foi um padre jesuíta espanhol que introduziu a poesia e o teatro na literatura brasileira. Foi aluno do Colégio dos Jesuítas de Coimbra e em 1553 veio para o Brasil Colônia com o objetivo de ajudar na doutrinação dos índios. José de Anchieta nasceu em San Cristóbal de La Laguna, em Tenerife, nas ilhas Canárias, Espanha, no dia 19 de março de 1534. Era filho de João Lopez de Anchieta, fidalgo basco, e Mência Dias de Clavijo y Lerena, descendente dos conquistadores de Tenerife. Anchieta estudou as primeiras letras em casa e em seguida ingressou na escola dos dominicanos quando aprendeu os conhecimentos da gramática latina. Aos 14 anos, em companhia de seu irmão mais velho, foi para Coimbra, Portugal, para estudar filosofia no Real Colégio das Artes e Humanidades. Com 16 anos ingressou no Colégio dos Jesuítas e no ano seguinte tornou-se noviço da Companhia de Jesus.', 'Quinhentismo', '../obras/autores/joseanchieta.jpeg'),
(4, 'Bento Teixeira', 'Bento Teixeira Pinto nasceu em Porto, Portugal, no ano de 1561. Filho de Manuel Álvares de Barros e de Leonor Rodrigues, cristãos novos, mudou-se com a família para o Brasil colônia, em 1567, instalando-se na Capitania do Espírito Santo. Bento Teixeira recebeu de sua mãe a doutrina judaica, no entanto, estudou em colégio jesuíta. Tentou seguir a carreira eclesiástica, mas desistiu. Depois da morte dos pais, mudou-se para Ilhéus na Bahia. Em 1584, casou-se com a cristã Filipa Raposo. Em seguida, Bento Teixeira transferiu-se para a Capitania de Pernambuco, onde em 1590 instalou uma escola em Olinda e se dedicou ao magistério e também ao comércio. Acusado pela mulher, de ser judeu e de rejeitar as práticas cristãs, Bento Teixeira passou a ser perseguido pela inquisição. Em 1589, Bento Teixeira foi julgado e absolvido pelo ouvidor da Vara Eclesiástica.', 'Barroco', '../obras/autores/bento.jpeg'),
(5, 'Gregório de Matos', 'Gregório de Matos Guerra nasceu em 1633, na cidade de Salvador, na Bahia, filho de um fidalgo português que se tornou senhor de engenho no Recôncavo Baiano com uma brasileira, Gregório de Matos se formou em Direito na Universidade de Coimbra, Portugal. Embora não se saiba muito sobre sua vida, acredita-se que ele tenha chegado a trabalhar como juiz na cidade de Alcácer do Sal, em Portugal. Em 1682, foi nomeado pelo rei português para ocupar um cargo eclesiástico em uma igreja de Salvador, mas, ao descobrir que precisaria fazer voto de castidade, desistiu. Abriu uma banca de advogado em Salvador e casou-se com Dona Maria dos Povos, com quem teve um filho, Gonçalo, em 1696, fixa-se em Recife, onde morre em 26 de novembro daquele ano.', 'Barroco', '../obras/autores/gregorio.jpg'),
(6, 'Cláudio Manuel da Costa', 'Cláudio Manuel da Costa nasceu na zona rural de Ribeirão do Carmo, hoje Mariana, em Minas Gerais, no dia 5 de junho de 1729. Era filho do português João Gonçalves da Costa, ligado à mineração, e Teresa Ribeira de Alvarenga, natural de Minas Gerais. De família rica, estudou no Colégio dos Jesuítas no Rio de Janeiro. Em 1753 formou-se em Direito pela Universidade de Coimbra. Ainda estudante, dedicou-se à poesia escrevendo vários versos. Depois de formado em Direito, regressou ao Brasil, em 1754, estabelecendo-se como advogado em Mariana e em Vila Rica, hoje a cidade de Ouro Preto. Entre 1762 e 1765 exerceu o cargo de Secretário do Governo da Capitania de Minas Gerais.', 'Arcadismo', '../obras/autores/claudiomanueldacosta.png'),
(7, 'Santa Rita Durão', 'Santa Rita Durão ou Frei José de Santa Rita Durão nasceu em Cata Preta, nos arredores de Mariana, em Minas Gerais, no ano de 1722. Estudou com os jesuítas no Rio de Janeiro. Foi para um seminário na Europa e nunca mais voltou ao Brasil. Santa Rita Durão formou-se em Filosofia e Teologia pela Universidade de Coimbra, alcançando o título de doutor. Durante a repressão do “período pombalino”, Durão foi para a Itália onde passou vinte anos. De volta a Coimbra, após a reforma realizada pelo Marquês de Pombal, passou a lecionar Teologia na Universidade de Coimbra e posteriormente foi nomeado Reitor da mesma Universidade.', 'Arcadismo', '../obras/autores/santaritadurao.jpeg'),
(8, 'Basílio da Gama', 'Basílio da Gama (1740–1795) foi um poeta brasileiro nascido em Tiradentes (MG). Estudou no Colégio dos Jesuítas e viajou pela Europa, onde entrou para a Arcádia Romana. Preso em Lisboa por suspeita de ligação com os jesuítas, foi perdoado por Pombal após escrever um poema para as núpcias da filha do ministro. Ganhou cargo público e escreveu o poema épico O Uraguai (1769), que critica os jesuítas e exalta Pombal, retratando o conflito nas missões do Rio Grande. Morreu em Lisboa em 1795 e é patrono da cadeira 4 da\n\nAcademia Brasileira de Letras.Basílio da Gama também produziu outras obras, como o poema Quitúbia (1791), além de traduções e versos ocasionais. Sua obra é marcada pela influência do Iluminismo e pelo contexto político da época, refletindo a relação entre Europa, Brasil colonial e os povos indígenas.', 'Arcadismo', '../obras/autores/basiliodagama.jpg'),
(9, 'Tomás Antônio Gonzaga', 'Tomás Antônio Gonzaga (1744–1807) foi um poeta e advogado português, conhecido por sua participação na Inconfidência Mineira. Nascido no Porto, estudou Direito na Universidade de Coimbra e exerceu cargos públicos em Portugal e no Brasil, como juiz-de-fora em Beja e Ouvidor Geral em Vila Rica. Acusado de envolvimento na Inconfidência, foi preso em 1789 e exilado para a Ilha de Moçambique, onde casou-se e teve filhos. Sua obra poética inclui o livro Marília de Dirceu (1792), dedicado à sua noiva, e a sátira Cartas Chilenas. Faleceu em 1807, deixando um legado importante na literatura colonial brasileira.', 'Arcadismo', '../obras/autores/tomasantoniogonzaga.jpg'),
(10, 'Antônio Gonçalves Dias', 'Gonçalves Dias nasceu em 1823, em Caxias (MA), filho de um comerciante português e de uma mulher mestiça. Estudou em Coimbra, Portugal, após a morte do pai, com apoio da madrasta e de colegas. Teve uma vida pessoal marcada por dificuldades: origem humilde, preconceito racial, saúde frágil, um casamento infeliz e a perda precoce da filha. Trabalhou como professor, funcionário público e participou de missões oficiais na Europa e no Norte do Brasil. Estudou a cultura indígena e a língua tupi. Morreu em 1864, aos 41 anos, em um naufrágio no litoral do Maranhão, sendo a única vítima do acidente. É patrono da cadeira 15 da Academia Brasileira de Letras.', 'Romantismo', '../obras/autores/antoniogoncalvesdias.jpeg'),
(11, 'Jóse de Alencar', 'José de Alencar (1829–1877) foi advogado, jornalista, político e um dos mais importantes romancistas do Brasil. Nasceu no Ceará e teve uma formação marcada pelo contato com a natureza e o sentimento nacionalista, herdado do pai revolucionário. Estudou Direito em São Paulo e atuou na imprensa e na política, sendo ministro da Justiça e deputado, embora não tenha alcançado o cargo de senador. Sua carreira literária começou com críticas contundentes à literatura oficial da época, e ele optou pelo romance como forma de expressar a identidade brasileira. Faleceu aos 48 anos, vítima de tuberculose. É o patrono da cadeira 23 da Academia Brasileira de Letras, escolhido por Machado de Assis, que o admirava profundamente.', 'Romantismo', '../obras/autores/josedealencar.jpeg'),
(12, 'Manuel Antônio Álvares de Azevedo', 'Álvares de Azevedo nasceu em 12 de setembro de 1831, em São Paulo, na casa de seu avô materno. Filho de Inácio Manuel Álvares de Azevedo e Maria Luísa Mota Azevedo, mudou-se com a família para o Rio de Janeiro em 1833. Foi aluno do Colégio Stoll e, mais tarde, do Colégio Pedro II. Em 1848, ingressou na Faculdade de Direito de São Paulo, onde se destacou como estudante e participou ativamente da vida intelectual e cultural. Conviveu com nomes importantes como Aureliano Lessa e Bernardo Guimarães, com quem formou uma república estudantil. Influenciado por autores românticos europeus, desenvolveu uma personalidade melancólica e introspectiva. Durante férias no Rio de Janeiro, em 1852, sofreu um acidente de cavalo que resultou\n\nem complicações de saúde. Após uma cirurgia, desenvolveu septicemia e faleceu em 25 de abril de 1852, aos 20 anos de idade.', 'Romantismo', '../obras/autores/manuelantonioalvares.jpg'),
(13, 'Casimiro de Abreu', 'Casimiro de Abreu nasceu em 4 de janeiro de 1839, no distrito de Barra de São João, Rio de Janeiro, e faleceu em 18 de outubro de 1860, aos 21 anos, vítima de tuberculose. É patrono da Cadeira nº 6 da Academia Brasileira de Letras, por escolha de Teixeira de Melo. Filho do português José Joaquim Marques Abreu e de Luísa Joaquina das Neves, teve uma origem considerada ilegítima, o que marcou sua infância. Viveu grande parte da juventude na Fazenda da Prata, em Correntezas. Estudou no Instituto Freeze, em Nova Friburgo, entre 1849 e 1852.', 'Romantismo', '../obras/autores/casimirodeabreu.jpg'),
(14, 'Antônio Frederico de Castro Alves', 'Castro Alves (Antônio Frederico de Castro Alves) nasceu em 14 de março de 1847, em Muritiba (BA), e faleceu em 6 de julho de 1871, em Salvador, aos 24 anos. É patrono da Cadeira nº 7 da Academia Brasileira de Letras. Filho de um médico e professor, perdeu a mãe na infância e iniciou cedo os estudos em Salvador, depois no Recife, onde entrou na Faculdade de Direito. Dedicou-se mais à poesia e à vida intelectual do que aos estudos formais. Transferiu-se para São Paulo em 1868. Sofreu um acidente que levou à amputação do pé e agravou seu estado de saúde, já afetado pela tuberculose. Passou seus últimos anos entre tratamentos e produção literária intensa. Morreu jovem, sendo lembrado como um dos grandes nomes do Romantismo no Brasil.', 'Romantismo', '../obras/autores/castroalves.jpeg'),
(15, 'Machado de Assis', 'Joaquim Maria Machado de Assis nasceu em 21 de junho de 1839, no Rio de Janeiro, e faleceu em 1908. Filho de Francisco José de Assis e Maria Leopoldina Machado de Assis, ficou órfão na infância e foi criado pela madrasta. Enfrentou problemas de saúde, como epilepsia e gaguez. Com formação escolar básica, adquiriu vasta cultura por conta própria. De origem humilde e negro, superou barreiras sociais e ingressou nos meios literário e público. Iniciou a carreira como tipógrafo e logo começou a publicar em jornais. Casou-se com Carolina Xavier de Novais e foi servidor do Ministério da Agricultura até sua morte.', 'Realismo', '../obras/autores/machadodeassis.jpeg'),
(16, 'Raul Pompeia', 'Raul Pompeia nasceu na cidade de Angra dos Reis (Rio de Janeiro) em 12 de abril de 1863. Estudo Direito na Faculdade do Largo de São Francisco, na cidade de São Paulo. Porém, não exerceu a atividade de advogado. Atuou em movimentos favoráveis à abolição da escravatura e pelo fim da monarquia e implantação da República. Porém, em função de suas posições polêmicas e, muitas vezes inflexíveis, chegou a se desentender com vários republicanos. Escreveu para o jornal Gazeta de Notícias. Neste jornal publicou sua grande obra “O Ateneu”. Em razão de suas posições políticas, Raul Pompeia entrou em conflito com Olavo Bilac. Suicidou-se, aos 32 anos, em 25 de dezembro de 1895.', 'Realismo', '../obras/autores/raulpompeia.jpg'),
(17, 'Júlia Lopes de Almeida', 'Nascida no Rio de Janeiro em 1862, foi uma das primeiras mulheres a se destacar na literatura brasileira. Estudou de forma particular e entrou na vida literária influenciada pelo Realismo e Naturalismo, abordando questões sociais e o papel da mulher na sociedade. Publicou romances, contos e crônicas, além de participar de causas femininas e educacionais. Sua escrita tratava de temas como a condição feminina, moralidade e críticas sociais, desafiando os padrões conservadores da época. Júlia também participou ativamente de movimentos em prol dos direitos das mulheres, sendo uma figura importante no contexto cultural e social do Brasil. Sua obra contribuiu para a abertura de espaço para escritoras mulheres no país.', 'Realismo', '../obras/autores/julialopesdealmeida.jpg'),
(18, 'Domingos Olímpio', 'Nasceu em Sobral, Ceará, em 1851. Formou-se em Direito e exerceu a profissão em sua terra natal. Seu trabalho literário tem forte influência regionalista, destacando aspectos do sertão nordestino e suas dificuldades. Também atuou como jornalista e advogado. Morreu em 1906, deixando obras importantes para o Realismo brasileiro. Sua narrativa buscava descrever com fidelidade a realidade social e geográfica do Nordeste, explorando conflitos humanos e ambientais. Domingos Olímpio é conhecido pelo romance O Sertanejo, que mostra a vida dura e o caráter dos habitantes do sertão. Sua obra oferece um panorama crítico e realista da sociedade brasileira, com ênfase nos problemas regionais.', 'Realismo', '../obras/autores/domingosolimpio.jpg'),
(19, 'Visconde de Taunay', 'Visconde de Taunay, nome completo Alfredo d\'Escragnolle Taunay, nasceu no Rio de Janeiro em 22 de fevereiro de 1843 e faleceu em 25 de janeiro de 1899. Foi escritor, militar, historiador e político. Formou-se em Engenharia Militar e participou da Guerra do Paraguai, experiência que influenciou várias de suas obras. Destacou-se na literatura brasileira como um autor de transição entre o Romantismo e o Realismo, com forte presença de regionalismo. Sua obra mais conhecida é Inocência (1872), que retrata a vida no interior do Brasil com observação detalhada e crítica sutil. Foi governador de Santa Catarina e membro do Instituto Histórico e Geográfico Brasileiro. Monarquista, afastou-se da vida pública após a Proclamação da República. É lembrado por sua contribuição à cultura e à literatura nacional.', 'Realismo', '../obras/autores/visconde.png'),
(20, 'Aluísio Azevedo', 'Aluísio Azevedo nasceu na cidade de São Luís, Maranhão, em 14 de abril de 1857.Em 1876, Aluísio de Azevedo mudou-se para o Rio de Janeiro com o objetivo de estudar Belas Artes, consolidando sua formação em desenho e pintura. Fundador da cadeira número quatro da Academia Brasileira de Letras e crítico social, este escritor naturalista foi autor de diversos livros. Durante grande parte de sua vida, Aluísio de Azevedo viveu daquilo que ganhava como escritor, mas ao entrar para a vida diplomática ele abandonou a produção literária. Sua carreira diplomática teve início em 1895. Ele serviu em diferentes países da América Latina, Europa e Ásia. Faleceu em Buenos Aires (Argentina), aos 56 anos, no dia 21 de janeiro de 1913.', 'Naturalismo', '../obras/autores/aluisioazevedo.jpg'),
(32, 'Júlio Ribeiro', 'Júlio Ribeiro (1845–1890) foi um importante jornalista, filólogo e romancista do Brasil, nascido em Sabará (MG). Abandonou a carreira militar para se dedicar ao ensino e ao jornalismo, onde se destacou pelo seu espírito polemista. Defendia uma gramática mais próxima da fala brasileira e participou ativamente da propaganda republicana. Seu romance A carne (1888) causou grande escândalo na época devido ao conteúdo sensual, sendo atacado por críticos e religiosos. Teve papel relevante na cultura brasileira do século XIX e é patrono da cadeira 24 da Academia Brasileira de Letras.', 'Naturalismo', '../obras/autores/julioribeiro.jpg'),
(33, 'Adolfo Caminha', 'Adolfo Caminha (1867–1897) foi um escritor brasileiro natural de Aracati, Ceará, e um dos principais nomes do naturalismo no Brasil. Mudou-se ainda criança para o Rio de Janeiro e ingressou na Marinha, chegando a segundo-tenente. Abandonou a carreira militar após um escândalo amoroso, ao fugir com a esposa de um alferes, indo viver com ela em Fortaleza. Sua obra é marcada por temas polêmicos e trágicos, como em A Normalista e Bom-Crioulo. Caminha faleceu jovem, aos 29 anos, vítima de tuberculose, deixando um legado literário ousado e inovador.', 'Naturalismo', '../obras/autores/adolfocaminha.jpeg'),
(34, 'Olavo Bilac', 'Olavo Bilac (1865–1918) foi um poeta, contista e jornalista brasileiro. É um dos principais nomes do Parnasianismo, movimento literário que valorizava a forma perfeita, rimas ricas e linguagem refinada. Autor da letra do Hino à Bandeira, destacou-se também pelo patriotismo. Foi membro fundador da Academia Brasileira de Letras e é lembrado como mestre da poesia formal na literatura brasileira. Bilac foi um escritor muito popular em sua época e atuou como ativista cívico. Participou de campanhas de incentivo ao serviço militar obrigatório e de valorização dos símbolos nacionais. Seu estilo buscava a harmonia entre a emoção e a técnica apurada. Apesar de ser um defensor da forma clássica, seus textos mantêm sensibilidade e beleza. É considerado o \"príncipe dos poetas brasileiros\", título que recebeu em vida.', 'Parnasianismo', '../obras/autores/olavobilac.jpg'),
(35, 'Raimundo Correia', 'Raimundo Correia (1859-1911) foi um poeta brasileiro, um dos mais destacados poetas do Parnasianismo - movimento essencialmente poético que reagiu contra os abusos sentimentalistas dos românticos. Raimundo da Mota de Azevedo Correia, conhecido como Raimundo Correia, nasceu a bordo de um navio, na baía de Mangunça, município de Cururupu, Maranhão, no dia 13 de maio de 1859. Era filho do desembargador português José da Mota de Azevedo Correia, descendente do duque de Caminha, e de Maria Clara Vieira da Mota de Azevedo Corrêa. Raimundo Correia estudou no Colégio Pedro II, no Rio de Janeiro. Em seguida, ingressou na Faculdade de Direito do Largo de São Francisco, em São Paulo. Nessa época, participou da fundação da “Revista de Ciências e Letras”, que se opunha aos ideais românticos.', 'Parnasianismo', '../obras/autores/raimundocorreia.png'),
(36, 'Alberto de Oliveira', 'Alberto de Oliveira (1857-1937) foi um poeta do Parnasianismo e professor brasileiro, considerado o mais perfeito dos parnasianos. Foi um dos fundadores da Academia Brasileira de Letras. Antônio Mariano Alberto de Oliveira, conhecido como Alberto de Oliveira, nasceu em Palmital do Saquarema, no Rio de Janeiro, no dia 28 de abril de 1857. Era filho de José Mariano de Oliveira, mestre de obras, e de Ana de Oliveira. Estudou o primário em escola pública na vila Nossa Senhora de Nazaré e cursou Humanidades em Niterói. Formou-se em Farmácia em 1883 e estudou Medicina até o terceiro ano, quando foi colega de Olavo Bilac. Entre 1893 e 1898 exerceu o cargo de diretor geral da Instrução Pública do Rio de Janeiro. Foi também professor de Português e de Literatura Brasileira no Colégio Pio-Americano e na Escola Normal. Foi um dos sócios fundadores da Academia Brasileira de Letras em 1897.', 'Parnasianismo', '../obras/autores/albertodeoliveira.jpg'),
(38, 'Alphonsus de Guimaraens', 'Alphonsus de Guimaraens nasceu em Ouro Preto, Minas Gerais, em 1870. Foi um dos principais poetas do Simbolismo no Brasil, conhecido pela forte presença do tema da morte da mulher amada em sua obra, inspirado pela perda precoce de sua prima e amada Constança. Estudou Direito em São Paulo, mas não chegou a concluir o curso, retornando a Minas Gerais, onde trabalhou como juiz e se dedicou à poesia. Sua produção é marcada pelo lirismo, pelo misticismo e pelo uso de símbolos religiosos, relacionando temas como a morte, a fé, a natureza e o amor idealizado. Alphonsus faleceu em Mariana, Minas Gerais, em 1921, deixando um legado importante para a literatura simbolista brasileira.', 'Simbolismo', '../obras/autores/alphonsusdeguimaraens.jpeg'),
(39, 'Augusto dos Anjos', 'Augusto dos Anjos nasceu em 1884 e é considerado um dos poetas mais críticos do Pré-modernismo brasileiro. Sua poesia revela influências do Simbolismo, especialmente no gosto pela morte, na angústia existencial e no uso intenso de metáforas. Autodeclarado “Cantor da poesia de tudo que é morto”, Augusto dos Anjos enfrentou rejeição inicial da crítica, que criticava seu vocabulário considerado mórbido e vulgar. Sua produção poética está concentrada em um único livro, Eu, publicado em 1912 e posteriormente reeditado como Eu e Outros Poemas. Morreu jovem, em 1914, deixando uma obra singular que influenciou gerações futuras.', 'Simbolismo', '../obras/autores/augustosdosanjos.jpeg'),
(40, 'Emiliano Perneta', 'Emiliano Perneta, poeta brasileiro, nasceu em Curitiba, Paraná, no dia 3 de janeiro de 1866, e faleceu na mesma cidade em 19 de janeiro de 1921. Considerado um dos principais nomes do simbolismo no Brasil, começou sua trajetória literária aos 17 anos, quando publicou seus primeiros poemas na revista O Díluculo, de Curitiba. Em 1888, mudou-se para São Paulo, onde se destacou como um dos fundadores da Folha Literária. No mesmo ano, lançou suas obras poéticas Músicas, de influência parnasiana, e Carta à Condessa d\'Eu. Além de sua produção poética, Perneta também teve uma carreira ativa no jornalismo, colaborando com importantes publicações da época, como o Diário Popular e a Gazeta de São Paulo.', 'Simbolismo', '../obras/autores/emilianoperneta.jpg'),
(41, 'Euclides da Cunha', 'Euclides da Cunha foi um escritor, sociólogo, engenheiro e jornalista brasileiro, conhecido principalmente pela obra Os Sertões (1902). Nascido em Cantagalo, Rio de Janeiro, estudou engenharia militar e trabalhou como engenheiro e jornalista. Sua obra mais famosa, Os Sertões, mistura história, sociologia e literatura, abordando a Guerra de Canudos, no interior da Bahia. A obra é uma análise crítica do sertanejo, da geografia e da violência social do Brasil. Euclides também se destacou pela defesa da ideia de que o Brasil deveria buscar uma identidade nacional, considerando seu povo e suas tradições. Faleceu em 1909, vítima de um acidente.', 'Pré-Modernismo', '../obras/autores/euclidesdacunha.jpeg'),
(42, 'Graça Aranha', 'Graça Aranha foi um escritor, crítico literário e diplomata brasileiro, nascido em São Luís, Maranhão. Foi um dos mais importantes representantes do Pré-modernismo e um dos fundadores da Academia Brasileira de Letras. Sua obra Canaã (1902) é considerada um marco do movimento literário, abordando o conflito das diferentes culturas no Brasil, principalmente a imigração europeia e o impacto da modernização nas relações sociais. Aranha também teve uma atuação importante como crítico literário e defendia a ideia de uma literatura brasileira autêntica, livre das influências europeias. Além disso, exerceu atividades diplomáticas e políticas no Brasil e no exterior. Faleceu em 1931.', 'Pré-Modernismo', '../obras/autores/gracaaranha.jpeg'),
(43, 'Monteiro Lobato', 'Monteiro Lobato foi um escritor, jornalista e editor brasileiro, nascido em Taubaté, São Paulo. É amplamente reconhecido por sua contribuição à literatura infantil, especialmente com a criação do Sítio do Picapau Amarelo. No entanto, sua obra para adultos também é significativa, com destaque para Cidades Mortas (1919), em que critica a desigualdade social e a exploração no Brasil. Lobato foi um grande defensor da industrialização do país e se opôs à mentalidade colonialista. Atuou também como editor e empresário, e suas ideias políticas foram controversas, defendendo uma modernização radical. Morreu em 1948, deixando um legado literário profundo e de grande alcance.', 'Pré-Modernismo', '../obras/autores/monteirolobato.jpeg'),
(44, 'Lima Barreto', 'Lima Barreto foi um escritor e jornalista brasileiro, nascido no Rio de Janeiro. Seu trabalho se caracteriza pela crítica social, com ênfase em temas como o racismo, as desigualdades sociais e as falhas da República Brasileira. Sua obra mais conhecida, Triste Fim de Policarpo Quaresma (1915), é uma sátira à sociedade brasileira, à classe política e ao nacionalismo da época. Lima Barreto também enfrentou dificuldades pessoais, incluindo problemas com alcoolismo e questões de saúde mental, que influenciaram sua visão de mundo. Apesar de sua produção literária notável, o autor foi amplamente ignorado pela crítica da época. Morreu em 1922, sem o reconhecimento que merecia, mas sua obra foi redescoberta mais tarde e passou a ser considerada fundamental para a literatura brasileira.', 'Pré-Modernismo', '../obras/autores/limabarreto.jpeg'),
(45, 'Carlos Drummond de Andrade', 'Carlos Drummond de Andrade foi um dos maiores poetas brasileiros, membro de destaque da primeira fase do Modernismo. Nascido em Itabira, Minas Gerais, Drummond começou a carreira literária nos anos 1920 e se tornou um dos nomes centrais da poesia moderna brasileira. Sua obra abrange temas como a angústia existencial, a busca por sentido, a crítica social e a reflexão sobre o papel do poeta na sociedade. Drummond foi também jornalista e tradutor. Entre suas obras mais importantes estão Alguma Poesia (1930), Sentimento do Mundo (1940) e A Rosa do Povo (1945).', 'Modernismo', '../obras/autores/carlosdrummonddeandrade.jpg'),
(46, 'Rachel de Queiroz', 'Rachel de Queiroz (1910-2003) foi uma escritora, jornalista e tradutora brasileira, uma das grandes figuras da literatura modernista e regionalista. Nascida em Fortaleza, Ceará, sua infância foi marcada pelas dificuldades do sertão nordestino, o que influenciou profundamente sua obra. Seu romance de estreia, "O Quinze" (1930), abordou a seca que devastou o Nordeste, sendo um marco da literatura brasileira e colocando Raquel como uma das principais vozes da geração de 30. A autora também teve uma importante carreira no jornalismo e foi a primeira mulher eleita para a Academia Brasileira de Letras, em 1977. Entre suas obras, destacam-se "Caminho de Pedras" (1937), "João Miguel" (1932) e "Dôra, Doralina" (1975), sempre abordando temas como a realidade social do Brasil e as relações familiares. Rachel também traduziu autores como William Faulkner e Graham Greene. Ela faleceu em 2003, deixando um importante legado literário.', 'Modernismo', '../obras/autores/racheldequeiroz.jpg'),
(47, 'Jorge Amado', 'Jorge Amado foi um escritor brasileiro, um dos mais traduzidos e conhecidos internacionalmente. Nascido na Bahia, sua obra está profundamente ligada à cultura e aos problemas sociais do Brasil, especialmente do Nordeste. Amado é famoso por suas histórias que misturam romance, política e questões sociais, como em Capitães da Areia (1937), Gabriela, Cravo e Canela (1958) e Dona Flor e Seus Dois Maridos (1966). Através de seus livros, ele abordou temas como a luta de classes, as desigualdades sociais e a luta pela liberdade, tornando-se um grande defensor dos direitos dos oprimidos.', 'Modernismo', '../obras/autores/jorgeamado.jpeg'),
(48, 'Mário de Andrade', 'Mário de Andrade foi um dos principais nomes do Modernismo no Brasil e um dos organizadores da histórica Semana de Arte Moderna de 1922. Nascido em São Paulo, foi poeta, romancista, musicista e crítico. Sua obra abrange diferentes formas de expressão, mas é principalmente conhecida por seu trabalho no campo da poesia e da prosa modernista, com destaque para o romance Macunaíma (1928), que é um dos maiores exemplos da literatura modernista brasileira. Mário defendia uma arte genuinamente brasileira, rompia com as influências europeias e buscava uma literatura que refletisse as realidades do país.', 'Modernismo', '../obras/autores/mariodeandrade.png'),
(49, 'Graciliano Ramos', 'Graciliano Ramos foi um escritor e jornalista brasileiro, um dos maiores nomes do Regionalismo e do Realismo Social no Brasil. Nascido em Quebrângulo, Alagoas, sua obra retratou com profundidade a miséria e as dificuldades do sertão nordestino, abordando as questões sociais e políticas da época. Seus romances mais conhecidos são Vidas Secas (1938), que narra a dura vida de uma família no sertão, e São Bernardo (1934), que explora a opressão e as relações de poder. Graciliano também foi prefeito de Palmeira dos Índios e preso durante o regime Vargas, experiência que influenciou sua escrita.', 'Modernismo', '../obras/autores/gracilianoramos.jpg'),
(50, 'Guimarães Rosa', 'João Guimarães Rosa nasceu em 27 de junho de 1908, em Cordisburgo, Minas Gerais. Formado em Medicina, ele trabalhou como médico e diplomata, tendo servido no exterior em diversas missões diplomáticas, especialmente na Alemanha e na França. Sua vivência em diferentes países e seu contato com diversas culturas influenciaram profundamente sua obra. Guimarães Rosa foi um dos mais importantes escritores brasileiros do século XX, e sua obra se destaca pela inovação linguística e pelo tratamento profundo das questões humanas e do sertão brasileiro. Faleceu em 19 de novembro de 1967, no Rio de Janeiro, deixando um legado literário que ainda é amplamente estudado e admirado.', 'Pós-Modernismo', '../obras/autores/guimaraesrosa.jpg'),
(51, 'Hilda Hilst', 'Hilda Hilst nasceu em 21 de abril de 1930, em Jaú, São Paulo. Filha de uma família tradicional, iniciou seus estudos em Direito, mas sempre teve uma forte inclinação para a literatura e as artes. Ao longo da vida, Hilda teve uma trajetória marcada pela busca por liberdade e pelo questionamento de normas sociais. Sua vivência em São Paulo e na cidade de Campinas, onde morou na Casa do Sol, foi fundamental para sua produção literária. Hilda Hilst também cultivou uma postura experimental, desafiando convenções e explorando novos caminhos para a escrita. Ela faleceu em 4 de fevereiro de 2004, deixando uma obra que a consolidou como uma das escritoras mais importantes da literatura brasileira contemporânea.', 'Pós-Modernismo', '../obras/autores/hildahilst.jpg'),
(52, 'Clarice Lispector', 'Clarice Lispector foi uma das autoras mais inovadoras e originais da literatura brasileira, associada ao Modernismo, especialmente em sua fase tardia. Nascida na Ucrânia, mas criada no Brasil, sua escrita é marcada pela introspecção psicológica e por uma abordagem filosófica da existência humana. A autora ficou conhecida por suas narrativas que exploram o universo interno dos personagens, suas dúvidas e angústias. Obras como Perto do Coração Selvagem (1943), A Hora da Estrela (1977) e O Lustre (1946) são fundamentais para a literatura brasileira, destacando seu estilo único.', 'Pós-Modernismo', '../obras/autores/claricelispector.jpg'),
(53, 'João Cabral de Melo Neto', 'João Cabral de Melo Neto (1920–1999) foi um poeta e diplomata brasileiro nascido no Recife (PE). Passou parte da infância em engenhos da família no interior de Pernambuco e estudou no Colégio dos Irmãos Maristas. Em 1942, publicou seu primeiro livro de poemas, Pedra do Sono. No Rio de Janeiro, ingressou no Itamaraty após ser aprovado em concurso em 1945, iniciando carreira diplomática com passagens por diversos países, incluindo o Senegal e Portugal, onde foi cônsul-geral na cidade do Porto. Sua obra, marcada pelo rigor formal e pela linguagem precisa, acompanhou-o durante toda a vida diplomática. Ganhou importantes prêmios literários, como o Prêmio Jabuti, o Prêmio Olavo Bilac e o Prêmio Bienal Nestlé. Foi eleito para a Academia Brasileira de Letras em 1968, tomando posse em 1969. Publicou obras essenciais da poesia brasileira moderna, como Morte e Vida Severina e A Educação pela Pedra. João Cabral se aposentou como embaixador em 1990 e teve sua Obra completa publicada em 1994. Morreu no Rio de Janeiro em 1999 e é patrono da cadeira 37 da Academia Brasileira de Letras.', 'Pós-Modernismo', '../obras/autores/joaocabral.jpg'),
(54, 'Padre Antônio Vieira', 'Padre Antônio Vieira (1608–1697) foi um religioso, missionário, escritor e orador português, natural de Lisboa. Ingressou na Companhia de Jesus aos 15 anos e, após completar os estudos teológicos, foi enviado para o Brasil, onde passou a exercer sua atividade como pregador, missionário e defensor dos direitos dos indígenas. Em 1654, passou a residir na cidade da Bahia, onde desenvolveu grande notoriedade por seus sermões e por sua luta contra a escravidão indígena. Vieira ficou famoso por sua eloquência e por sua visão política e religiosa, refletida em sua obra literária. Escreveu diversos sermões, cartas e tratados que abordavam questões sociais, políticas e religiosas, sendo considerado um dos maiores oradores do Barroco brasileiro. Em 1655, publicou o Sermão da Sexagésima, uma de suas obras mais significativas, e, no ano seguinte, foi nomeado confessor da rainha de Portugal, o que lhe conferiu uma grande influência.', 'Barroco', '../obras/autores/padrevieira.jpg');
INSERT INTO `obras` (`id`, `titulo`, `autor`, `escola_literaria`, `capa`, `descricao`, `arquivo`, `id_autor`) VALUES
(1, 'A Carta', 'Pero Vaz de Caminha', 'Quinhentismo', '../obras/capas/a carta.png', 'A Carta de Pero Vaz de Caminha é o documento no qual Pero Vaz de Caminha registrou as suas impressões sobre a terra que posteriormente viria a ser chamada de Brasil. É o primeiro documento escrito da história do Brasil. Costuma ser considerada marco inicial da obra literária brasileira, apesar de, formalmente, ser documento de mero registro, já que traz em suas linhas a escrita da época, o estilo; e, nas entrelinhas, conta muito da história oculta do descobrimento.
INSERT INTO `obras` (`id`, `titulo`, `autor`, `escola_literaria`, `capa`, `descricao`, `arquivo`, `id_autor`) VALUES
(52, 'Memórias Póstumas de Brás Cubas', 'Machado de Assis', 'Realismo', '../obras/capas/memorias postumas.png', 'Publicado em 1881, o romance é narrado por Brás Cubas, um defunto-autor que conta sua vida com ironia e crítica mordaz. Sem compromisso com convenções morais, expõe as hipocrisias da sociedade, o egoísmo e a futilidade da existência. A obra rompe com a estrutura tradicional, usa capítulos curtos e digressões filosóficas. É considerada o marco inicial do Realismo no Brasil e se destaca por sua linguagem inovadora, humor ácido e crítica à elite carioca e ao passado escravocrata do país.', 'http://www.dominiopublico.gov.br/pesquisa/DetalheObraDownload.do?select_action=&co_obra=16953&co_midia=2', NULL),
(53, 'Dom Casmurro', 'Machado de Assis', 'Realismo', '../obras/capas/dom casmurro.png', 'Publicado em 1899, o livro apresenta a história de Bentinho, que revisita seu passado para relatar sua relação com Capitu e a suspeita de traição. A narrativa é marcada por ciúmes, memória seletiva e subjetividade extrema. A ambiguidade conduz o leitor à dúvida: Capitu traiu ou não? A obra é uma das mais cobradas nos vestibulares por seu narrador não confiável, pelo tratamento psicológico das personagens e por abordar temas como aparência versus verdade e machismo estrutural.', 'http://www.dominiopublico.gov.br/pesquisa/DetalheObraDownload.do?select_action=&co_obra=16931&co_midia=2', NULL),
(54, 'Quincas Borba', 'Machado de Assis', 'Realismo', '../obras/capas/quincas borba.png', 'Publicado em 1891, o romance acompanha Rubião, herdeiro do filósofo Quincas Borba, que adota o Humanitismo, doutrina fictícia e irônica criada pelo amigo. Rubião se muda para o Rio de Janeiro e, ingênuo, acaba sendo explorado por pessoas interesseiras. A obra satiriza o positivismo, critica o materialismo da sociedade e revela a degradação emocional e moral do protagonista. Muito cobrada por sua crítica social, estilo irônico e estrutura marcada pelo realismo psicológico.', 'http://www.dominiopublico.gov.br/pesquisa/DetalheObraDownload.do?select_action=&co_obra=16972&co_midia=2', NULL),
(55, 'Helena', 'Machado de Assis', 'Realismo', '../obras/capas/helena.png', 'Publicado em 1876, é um romance de transição entre o Romantismo e o Realismo. Conta a história de Helena, jovem filha ilegítima de um senador que é acolhida pela nova família após a morte do pai. O enredo trata de moral, status social e amores impossíveis. Apesar do tom romântico, a obra já revela elementos do estilo realista de Machado, como a análise das aparências sociais e a crítica sutil à hipocrisia burguesa. Muito abordada em vestibulares por representar a evolução do autor.', 'http://www.dominiopublico.gov.br/pesquisa/DetalheObraDownload.do?select_action=&co_obra=16940&co_midia=2', NULL),
(56, 'Contos', 'Machado de Assis', 'Realismo', '../obras/capas/contos.png', 'Os contos de Machado foram publicados entre 1870 e 1906, e destacam-se por sua economia narrativa, ironia fina e profundidade psicológica. \n\n“O Espelho” (1882) analisa a dualidade entre o “eu interior” e o “eu social”. \n\n“A Cartomante” (1884) trata de destino, autoengano e consequências da fé cega. \n\n“Missa do Galo” (1893) sugere desejo e tensão numa conversa ambígua entre um jovem e uma mulher casada. Esses contos são muito cobrados por condensarem, em poucas páginas, o estilo único e crítico de Machado de Assis.', 'http://www.dominiopublico.gov.br/pesquisa/DetalheObraDownload.do?select_action=&co_obra=1878&co_midia=2', NULL),
(57, 'O Ateneu', 'Raul Pompeia', 'Realismo', '../obras/capas/o ateneu.png', 'Romance de formação narrado por Sérgio, que relembra sua experiência como aluno interno no colégio Ateneu. A obra mostra a perda da inocência, o amadurecimento e a descoberta das hipocrisias do mundo adulto. Mistura traços do Romantismo, Realismo e Impressionismo, com linguagem refinada e análise psicológica. Faz crítica à educação da elite, à vaidade, ao autoritarismo e às aparências sociais. É a obra mais famosa de Raul Pompeia e uma das mais cobradas em vestibulares.', 'http://www.dominiopublico.gov.br/pesquisa/DetalheObraDownload.do?select_action=&co_obra=17440&co_midia=2', NULL),
(58, 'Uma Tragédia no Amazonas', 'Raul Pompeia', 'Realismo', '../obras/capas/uma tragedia no amazonas.png', 'Novela escrita quando o autor tinha apenas 17 anos. A história acompanha um drama de vingança e honra ambientado na região amazônica, envolvendo paixões violentas e conflitos familiares. O texto tem forte influência do Romantismo, com tom trágico e personagens movidos por emoções extremas. Embora pouco cobrado, mostra o talento precoce do autor e seu domínio narrativo já na juventude.', 'http://www.dominiopublico.gov.br/pesquisa/DetalheObraDownload.do?select_action=&co_obra=17442&co_midia=2', NULL),
(59, 'As Joias da Coroa', 'Raul Pompeia', 'Realismo', '../obras/capas/as joias da coroa.png', 'Coletânea de contos inicialmente publicada em folhetins. Reúne narrativas curtas que exploram temas como sociedade, valores morais, amor e orgulho, com linguagem elegante e olhar crítico. A obra apresenta influência romântica, mas já aponta traços realistas. Apesar de pouco conhecida, é relevante para entender a transição de estilo do autor e seu domínio sobre o gênero narrativo breve.', 'http://www.dominiopublico.gov.br/pesquisa/DetalheObraDownload.do?select_action=&co_obra=17439&co_midia=2', NULL),
(60, 'Canções sem Metro', 'Raul Pompeia', 'Realismo', '../obras/capas/cancoes sem metro.png', 'Reunião de poemas e textos em prosa poética, marcados por tom melancólico, filosófico e sentimental. Expressa emoções íntimas, angústias existenciais e reflexões sobre a vida e a morte. É uma obra lírica, com influências do ultrarromantismo, especialmente na idealização da dor e da solidão. Mostra o lado mais sensível de Raul Pompeia antes de seu engajamento político e social.', NULL, NULL),
(61, 'Crônicas e artigos políticos', 'Raul Pompeia', 'Realismo', '../obras/capas/cronicas e artigos politicos.png', 'Textos publicados em jornais como a Gazeta de Notícias, abordando temas políticos, sociais e culturais do Brasil do final do século XIX. Defendia com veemência a República e o fim da Monarquia, além da abolição da escravidão. Escritos com estilo direto, combativo e muitas vezes polêmico, esses textos revelam o intelectual engajado e ajudam a entender os conflitos que marcaram sua vida. Embora menos literários, são importantes documentos históricos.', NULL, NULL),
(62, 'A Família Medeiros', 'Júlia Lopes de Almeida', 'Realismo', '../obras/capas/a familia medeiros.png', 'Neste romance, Júlia Lopes de Almeida retrata os conflitos e a decadência de uma família tradicional brasileira diante das transformações sociais do final do século XIX. A autora explora temas como honra, aparência social, hipocrisia burguesa e o papel da mulher na família patriarcal. A trama gira em torno dos membros da família Medeiros, cujas tensões internas e segredos revelam o desgaste de antigos valores. Além de denunciar os valores falidos da elite carioca, a obra aborda a perda de prestígio social e os jogos de interesse. A escrita realista de Júlia revela sua crítica à estrutura patriarcal e ao machismo dominante. A autora também destaca o sofrimento emocional das mulheres presas a um sistema que limita suas escolhas.', NULL, NULL),
(63, 'Memórias de Marta', 'Júlia Lopes de Almeida', 'Realismo', '../obras/capas/memorias de marta.png', 'Narrado em primeira pessoa, o livro apresenta o relato íntimo de Marta, uma mulher sensível e reflexiva que recorda momentos marcantes de sua vida. A obra, pioneira ao dar voz a uma protagonista feminina complexa, aborda temas como identidade, maternidade, amor e sacrifício, além de propor uma crítica velada à condição feminina na sociedade brasileira da época. Marta compartilha suas dores, escolhas e arrependimentos, convidando o leitor a mergulhar em suas emoções. O estilo intimista aproxima a autora das experiências de muitas mulheres de seu tempo. A narrativa é também um instrumento de denúncia contra o silêncio imposto às mulheres burguesas.', NULL, NULL),
(65, 'O Retrato de Sylvia', 'Júlia Lopes de Almeida', 'Realismo', '../obras/capas/o retrato de sylvia.png', 'Neste romance psicológico e sensível, Júlia Lopes de Almeida retrata o processo de construção da identidade feminina por meio da figura de Sylvia, uma mulher idealizada pelo narrador. À medida que a narrativa se desenvolve, o \"retrato\" vai se desconstruindo, revelando as complexidades e contradições da personagem. O livro propõe reflexões sobre a idealização do amor e o lugar da mulher na sociedade. O narrador, fascinado por Sylvia, revela mais sobre si mesmo do que sobre a jovem. A figura de Sylvia representa o conflito entre o ser e o parecer feminino. A autora faz uso da metalinguagem e da introspecção para discutir os limites entre o real e o imaginário nas relações humanas.', NULL, NULL),
(66, 'Correspondência de Aluísio Azevedo e Júlia Lopes de Almeida', 'Júlia Lopes de Almeida', 'Realismo', '../obras/capas/correspondencia de aluisio azevedo e julia lopes de almeida.png', 'Essa obra reúne cartas trocadas entre dois grandes nomes do Naturalismo e do Realismo brasileiros, revelando não só o relacionamento pessoal e literário entre Aluísio e Júlia, como também aspectos da cena literária da virada do século XIX para o XX. A correspondência ilumina debates sobre literatura, política, questões de gênero e a atuação intelectual da época. As cartas revelam a admiração mútua entre os autores e sua luta por reconhecimento no meio literário. Júlia, uma das primeiras mulheres a se destacar nesse espaço, mostra-se crítica e articulada. A coletânea também é um importante documento histórico, lançando luz sobre a posição da mulher intelectual no Brasil do início do século XX.', NULL, NULL),
(67, 'Luzia-Homem', 'Domingos Olímpio', 'Realismo', '../obras/capas/luzia-homem.png', 'Considerada a obra-prima de Domingos Olímpio, Luzia-Homem é um romance regionalista que retrata a dura realidade do sertão nordestino no século XIX. A protagonista, Luzia, é uma mulher forte e corajosa que desafia as normas de gênero ao agir com bravura masculina em defesa de sua honra. Ao vestir-se como homem e enfrentar cangaceiros e injustiças, Luzia rompe com os papéis tradicionais da mulher nordestina. O romance denuncia a opressão social e a miséria do povo sertanejo, explorando temas como seca, vingança, violência e resistência feminina. É um marco do realismo social na literatura brasileira.', 'http://www.dominiopublico.gov.br/pesquisa/DetalheObraDownload.do?select_action=&co_obra=16618&co_midia=2', NULL),
(68, 'O Almirante', 'Domingos Olímpio', 'Realismo', '../obras/capas/o almirante.png', 'O Almirante é um romance inacabado de Domingos Olímpio, publicado postumamente. A obra tem como pano de fundo a vida política e social do final do século XIX, destacando figuras da Marinha brasileira e os bastidores do poder. Com linguagem crítica e observadora, o autor discute questões como o autoritarismo, a vaidade política e o conflito entre ética e ambição. Apesar de não ter sido concluído, o romance revela a preocupação de Olímpio com o Brasil urbano e institucional, contrastando com a temática rural de Luzia-Homem.', NULL, NULL),
(69, 'A perdição', 'Domingos Olímpio', 'Realismo', '../obras/capas/a perdicao.png', 'Obra menos difundida, A Perdição segue a linha dramática da escrita de Domingos Olímpio, abordando os dilemas humanos diante da moral, do desejo e do destino. A história apresenta personagens marcados por escolhas trágicas, colocando em foco a luta interna entre paixão e honra. Embora haja poucos registros amplamente disponíveis dessa obra, acredita-se que ela continue a temática do sofrimento humano diante das pressões sociais, mantendo o estilo direto, descritivo e emocional característico do autor.', NULL, NULL),
(70, 'Rochedos que choram', 'Domingos Olímpio', 'Realismo', '../obras/capas/rochedos que choram.png', 'Este título evoca uma narrativa poética e intensa, em que o sertão novamente aparece como cenário para tragédias humanas. Rochedos que choram é um romance simbólico que mescla realismo e lirismo para retratar dores profundas de personagens marginalizados. A história gira em torno da perda, do isolamento e da resistência silenciosa dos que vivem à margem da sociedade. A obra reforça o tom social e emocional da literatura de Olímpio, embora seja menos conhecida e pouco explorada em estudos acadêmicos', NULL, NULL),
(71, 'Túnica de Nessus', 'Domingos Olímpio', 'Realismo', '../obras/capas/tunica de nessus.png', 'Com forte carga alegórica, Túnica de Nessus remete ao mito grego da peça de roupa envenenada que destrói seu portador. Na obra, Olímpio utiliza essa metáfora para tratar de traições, destruição moral e sofrimento causado por relações tóxicas. O romance expõe as feridas humanas invisíveis, alimentadas por ciúmes, falsidade e corrupção moral. A narrativa reflete o estilo maduro do autor e sua crítica à hipocrisia da sociedade. A obra tem um tom mais psicológico, diferenciado de seus textos sobre o sertão.', NULL, NULL),
(72, 'Inocência', 'Visconde de Taunay', 'Realismo', '../obras/capas/inocencia.png', 'Inocência é um romance regionalista e romântico que se passa no interior de Mato Grosso. A história gira em torno de Inocência, uma jovem bela e ingênua, que vive sob o controle rígido do pai. Ao conhecer o médico Cirino, por quem se apaixona, surge um conflito entre o amor proibido e as convenções sociais. A narrativa tem traços do romantismo, mas também já apresenta elementos realistas, com forte ambientação rural, costumes locais e crítica à opressão feminina. É considerada uma das primeiras obras da literatura brasileira a retratar o sertão com profundidade descritiva e sensibilidade psicológica.', 'http://www.dominiopublico.gov.br/pesquisa/DetalheObraDownload.do?select_action=&co_obra=17500&co_midia=2', NULL),
(73, 'A Retirada da Laguna', 'Visconde de Taunay', 'Realismo', '../obras/capas/a retirada da laguna.png', 'Baseado em sua experiência pessoal como militar, Visconde de Taunay narra neste livro os horrores vividos durante a retirada das tropas brasileiras no episódio trágico da Guerra do Paraguai, em 1867. Misturando relato histórico e literário, a obra descreve com realismo a fome, o frio, as doenças e o sofrimento dos soldados brasileiros. Ao mesmo tempo, exalta a coragem, o sacrifício e o patriotismo. É um dos primeiros exemplos de literatura de guerra no Brasil, combinando memória pessoal, crítica militar e análise humana profunda.', 'http://www.dominiopublico.gov.br/pesquisa/DetalheObraDownload.do?select_action=&co_obra=17499&co_midia=2', NULL),
(74, 'Ouro Sobre Azul', 'Visconde de Taunay', 'Realismo', '../obras/capas/ouro sobre azul.png', 'Esse romance menos conhecido de Taunay tem um tom mais leve e irônico. A história retrata a vida de jovens da elite carioca do século XIX, com foco em suas vaidades, superficialidades e falsas aparências. A expressão “ouro sobre azul” sugere algo perfeito, ideal — justamente o que o autor ironiza ao mostrar personagens envoltos em luxo e ambição, mas vazios de valores morais. A obra funciona como uma crítica social sutil à elite urbana, diferente do tom mais dramático de Inocência ou A Retirada da Laguna.', NULL, NULL),
(76, 'Lágrimas do Coração', 'Visconde de Taunay', 'Realismo', '../obras/capas/lagrimas do coracao.png', 'Esta obra se insere no estilo sentimental típico do romantismo brasileiro. Com tom melancólico e linguagem refinada, Lágrimas do Coração reúne narrativas ou reflexões sobre amores impossíveis, perdas e sofrimentos da alma. Taunay dá voz à dor emocional dos personagens com grande sensibilidade, refletindo sobre o destino, a saudade e a fragilidade humana. Embora menos famosa, a obra reforça seu talento em explorar o emocional, com destaque para os valores da honra, da família e da moral.', NULL, NULL),
(77, 'Céus e Terras do Brasil', 'Visconde de Taunay', 'Realismo', '../obras/capas/ceus e terras do brasil.png', '“Céus e Terras do Brasil” é uma coletânea de textos em que o Visconde de Taunay descreve, com sensibilidade e riqueza de detalhes, suas impressões sobre as paisagens naturais, o povo e os costumes do interior do Brasil. A obra reúne ensaios e crônicas de viagem, escritos com olhar de naturalista e viajante, ao longo de suas andanças pelo território brasileiro durante o século XIX. Com um estilo lírico e ao mesmo tempo científico, Taunay observa as serras, planícies, rios e florestas, mas também reflete sobre a vida nos rincões do país. A obra valoriza o cenário nacional e o Brasil profundo, demonstrando admiração pela natureza e pela diversidade cultural. É um dos melhores exemplos da prosa descritiva brasileira oitocentista, mesclando informação geográfica com apreciação estética.', 'http://www.dominiopublico.gov.br/pesquisa/DetalheObraDownload.do?select_action=&co_obra=43338&co_midia=2', NULL),
(78, 'O Cortiço', 'Aluísio Azevedo', 'Naturalismo', '../obras/capas/o cortico.png', 'Principal obra naturalista da literatura brasileira, O Cortiço retrata o cotidiano de um conjunto habitacional popular no Rio de Janeiro do século XIX. O autor descreve, com olhar científico e impessoal, como o meio ambiente, a hereditariedade e as condições sociais moldam o comportamento dos moradores. O romance é marcado por personagens múltiplos, representando diferentes grupos étnicos e sociais. Conflitos de classe, racismo, violência e sexualidade são tratados de forma direta, seguindo a estética naturalista. A obra denuncia as desigualdades urbanas e a animalização do homem em meio à miséria.', 'http://www.dominiopublico.gov.br/pesquisa/DetalheObraDownload.do?select_action=&co_obra=16534&co_midia=2', NULL),
(79, 'Casa de Pensão', 'Aluísio Azevedo', 'Naturalismo', '../obras/capas/casa de pensao.png', 'Neste romance de transição entre o Realismo e o Naturalismo, Aluísio Azevedo critica os valores da classe média urbana carioca. A trama gira em torno de Amâncio, um jovem do interior que se muda para a capital e vai morar em uma pensão repleta de intrigas, falsidades e jogos de interesse. A obra analisa como o ambiente urbano influencia negativamente o comportamento humano, levando o protagonista à decadência moral. A pensão funciona como microcosmo da sociedade hipócrita e oportunista da época. É uma crítica social contundente, marcada por observação psicológica e denúncia dos vícios burgueses.', 'http://www.dominiopublico.gov.br/pesquisa/DetalheObraDownload.do?select_action=&co_obra=16529&co_midia=2', NULL),
(80, 'O Mulato', 'Aluísio Azevedo', 'Naturalismo', '../obras/capas/o mulato.png', 'Primeiro romance naturalista do Brasil, O Mulato denuncia o preconceito racial, o fanatismo religioso e a hipocrisia social no Maranhão do século XIX. A história acompanha Raimundo, um jovem mulato educado na Europa, que volta ao Brasil e enfrenta a rejeição da sociedade por causa de sua origem racial. O livro combina crítica social com análise determinista da realidade brasileira, destacando o peso da cor da pele e da tradição escravocrata. A obra também questiona a atuação da Igreja e a falsa moral das elites. Foi revolucionária em sua época por tratar diretamente do racismo e da desigualdade.', 'http://www.dominiopublico.gov.br/pesquisa/DetalheObraDownload.do?select_action=&co_obra=16537&co_midia=2', NULL),
(81, 'O Homem', 'Aluísio Azevedo', 'Naturalismo', '../obras/capas/o homem.png', 'O Homem é um romance que continua a abordagem naturalista de Azevedo, mostrando a formação do caráter humano a partir da influência do meio, da hereditariedade e da educação. A trama acompanha a vida de um homem desde a infância até a vida adulta, focando na construção de sua identidade e nas pressões sociais que determinam suas escolhas. O autor reforça a visão determinista do ser humano como produto das circunstâncias. É uma obra mais filosófica e reflexiva, com forte crítica ao moralismo e à estrutura social.', 'http://www.dominiopublico.gov.br/pesquisa/DetalheObraDownload.do?select_action=&co_obra=7408&co_midia=2', NULL),
(82, 'O Livro de uma Sogra', 'Aluísio Azevedo', 'Naturalismo', '../obras/capas/o livro de uma sogra.png', 'Com tom satírico e irônico, esta obra é composta por uma série de cartas escritas por uma sogra que dá conselhos à filha sobre como “dominar” o marido. A autora fictícia critica o casamento, a maternidade e a vida doméstica com humor ácido. A obra escancara a hipocrisia das relações familiares da época e expõe, de forma cômica, o controle que muitas mulheres tentavam exercer nos bastidores dos lares burgueses. Apesar do tom leve, o livro faz uma crítica à falsa moral, ao machismo e às relações de poder dentro do casamento. É um dos melhores exemplos do lado cômico e crítico de Azevedo.', 'http://www.dominiopublico.gov.br/pesquisa/DetalheObraDownload.do?select_action=&co_obra=16536&co_midia=2', NULL),
(254, 'O Padre Belchior de Pontes', 'Júlio Ribeiro', 'Naturalismo', '../obras/capas/o padre belchior de pontes.png', 'Romance histórico dividido em dois volumes, ambientado na São Paulo colonial. A trama gira em torno do amor impossível entre o jovem Belchior, de origem modesta, e Branca, pertencente a uma família nobre. A obra critica as desigualdades sociais e os conflitos morais da época. Júlio Ribeiro utiliza a ambientação para refletir sobre as estruturas sociais e religiosas. É uma narrativa com forte componente documental e estilisticamente elaborada.', NULL, NULL),
(255, 'grammatica portugueza', 'Júlio Ribeiro', 'Naturalismo', '../obras/capas/gramatica portugueza.png', 'Primeira gramática do português voltada à realidade brasileira. Júlio Ribeiro propõe uma abordagem mais prática e próxima do uso cotidiano da língua no Brasil, rompendo com o tradicionalismo lusitano. Foi inovadora, mas posteriormente superada por estudos linguísticos mais modernos. Defendia a ideia de que o português do Brasil devia ter normas próprias. A obra gerou debates acalorados na época e é considerada um marco da filologia nacional.', NULL, NULL),
(256, 'Cartas sertanejas', 'Júlio Ribeiro', 'Naturalismo', '../obras/capas/cartas sertanejas.png', 'Conjunto de textos publicados em forma de cartas no Diário Mercantil. Nele, Júlio Ribeiro responde às críticas feitas à sua gramática e ideias. Usa ironia, erudição e análise linguística para defender suas posições e criticar os opositores. É também um exercício de estilo e argumentação. Essas cartas reforçam sua imagem de intelectual combativo e engajado.', NULL, NULL),
(257, 'A Carne', 'Júlio Ribeiro', 'Naturalismo', '../obras/capas/a carne.png', 'Romance naturalista e sua obra mais polêmica. Conta a história da paixão intensa entre Lenita e Manuel, tratando de temas como sensualidade, moral e liberdade feminina. Foi alvo de ataques por parte de religiosos e conservadores, e marcou época pelo tom ousado. A narrativa questiona os tabus da sociedade patriarcal. Tornou-se um símbolo da luta contra o moralismo conservador.', 'http://www.dominiopublico.gov.br/pesquisa/DetalheObraDownload.do?select_action=&co_obra=16684&co_midia=2', NULL),
(258, 'Uma polêmica célebre', 'Júlio Ribeiro', 'Naturalismo', '../obras/capas/uma polemica celebre.png', 'Publicação póstuma que reúne os artigos da famosa disputa entre Júlio Ribeiro e o padre Sena Freitas, desencadeada pelas críticas a A Carne. A obra documenta a veemência do autor na defesa da liberdade artística e do pensamento republicano e anticlerical. Mostra como as ideias progressistas de Ribeiro colidiam com o conservadorismo religioso. É um registro importante do pensamento crítico da época.', NULL, NULL),
(259, 'Judith e Lágrimas de um crente', 'Adolfo Caminha', 'Naturalismo', '../obras/capas/judith e lagrimas de um crente.png', 'Coletânea com dois contos de tom dramático e moral: “Judith” trata da culpa e paixão de uma mulher, enquanto “Lágrimas de um Crente” foca o conflito de fé de um homem. Ambas evidenciam o pessimismo típico do naturalismo. As histórias mostram personagens dominados por forças internas e sociais que os conduzem ao sofrimento. São contos breves, mas com profundidade emocional. Apresentam traços do estilo que Caminha desenvolveria mais tarde.', NULL, NULL),
(260, 'A normalista', 'Adolfo Caminha', 'Naturalismo', '../obras/capas/a normalista.png', 'Conta a história de Maria do Carmo, jovem que deseja estudar para ser professora, mas sofre com o moralismo da sociedade de Fortaleza no século XIX. O romance denuncia o machismo e a hipocrisia social, com crítica à repressão feminina. A protagonista vive entre o desejo de independência e a rigidez social. Caminha retrata com precisão o ambiente provinciano e o peso das convenções sociais sobre as mulheres. É um retrato fiel da luta feminina contra os limites impostos pela moral da época.', 'http://www.dominiopublico.gov.br/pesquisa/DetalheObraDownload.do?select_action=&co_obra=16512&co_midia=2', NULL),
(261, 'No país dos ianques', 'Adolfo Caminha', 'Naturalismo', '../obras/capas/no pais dos ianques.png', 'Relato de viagem aos Estados Unidos, onde Caminha observa os costumes e o modo de vida norte-americano. O livro contrasta a modernidade dos EUA com a realidade brasileira, de forma crítica e descritiva. Há momentos de crítica ao materialismo e à desigualdade percebida na sociedade americana. Reflete o olhar de um brasileiro sobre o avanço tecnológico e a cultura ocidental. Pode ser útil em análises culturais e sociais comparativas.', 'http://www.dominiopublico.gov.br/pesquisa/DetalheObraDownload.do?select_action=&co_obra=20929&co_midia=2', NULL),
(262, 'Bom-Crioulo', 'Adolfo Caminha', 'Naturalismo', '../obras/capas/bom-crioulo.png', 'Ambientado num navio da Marinha, o romance narra a relação homoafetiva entre Amaro, um marinheiro negro, e Aleixo, um jovem branco. A obra quebra tabus ao tratar abertamente de temas como racismo, homossexualidade e violência. Considerada inovadora para a época, é um marco do naturalismo brasileiro. Com forte crítica ao preconceito racial e à repressão sexual, o livro causou escândalo entre os leitores do século XIX. A narrativa mostra a degradação moral de Amaro e culmina em um desfecho trágico, típico do determinismo naturalista.', 'http://www.dominiopublico.gov.br/pesquisa/DetalheObraDownload.do?select_action=&co_obra=16513&co_midia=2', NULL),
(263, 'Tentação', 'Adolfo Caminha', 'Naturalismo', '../obras/capas/tentacao.png', 'A história gira em torno de Basílio, seminarista que abandona a vida religiosa por amor. O livro aborda o conflito entre desejo e valores religiosos, com crítica à repressão sexual e à culpa católica. O protagonista é arrastado por impulsos que não consegue controlar, revelando o conflito entre instinto e fé. A obra expõe as fragilidades humanas diante da disciplina religiosa. É uma das narrativas mais introspectivas de Caminha.', 'http://www.dominiopublico.gov.br/pesquisa/DetalheObraDownload.do?select_action=&co_obra=16515&co_midia=2', NULL),
(264, 'Tarde', 'Olavo Bilac', 'Parnasianismo', '../obras/capas/tarde.png', 'É a última obra publicada por Olavo Bilac em vida. Nela, o poeta apresenta uma poesia mais introspectiva, marcada por uma visão melancólica sobre a vida, o tempo e a perda das ilusões. Embora mantenha o rigor formal característico do parnasianismo, os temas abordados revelam um tom mais reflexivo e até mesmo pré-simbolista. A passagem do tempo e a proximidade da morte ganham destaque, fazendo da obra uma espécie de testamento poético. A precisão da forma permanece, mas com um conteúdo mais emocional e filosófico.', 'http://www.dominiopublico.gov.br/pesquisa/DetalheObraDownload.do?select_action=&co_obra=17314&co_midia=2', NULL),
(265, 'Poesias', 'Olavo Bilac', 'Parnasianismo', '../obras/capas/poesias.png', 'Foi a primeira coletânea de poemas publicada por Bilac e é considerada uma das expressões mais puras do parnasianismo brasileiro. A obra valoriza a perfeição estética, o uso refinado da linguagem e a estrutura rigorosa dos sonetos. Os temas mais comuns são o amor idealizado, a exaltação da beleza clássica, a natureza e o culto à forma perfeita. É nessa obra que Bilac se consagra como um mestre da métrica e do verso regular, tornando-se referência no movimento literário que prioriza a arte pela arte.', NULL, NULL),
(266, 'Crônicas e novelas', 'Olavo Bilac', 'Parnasianismo', '../obras/capas/cronicas e novelas.png', 'Reúne textos em prosa nos quais Bilac revela um olhar atento e crítico sobre o cotidiano da sociedade urbana do final do século XIX. Embora não seja poesia, a obra mantém o estilo refinado e culto do autor. As crônicas abordam temas sociais, comportamentais e morais, muitas vezes com leve ironia e observações perspicazes. O autor demonstra aqui sua versatilidade, transitando com facilidade entre poesia e prosa, sem perder o controle estético da linguagem.', NULL, NULL),
(267, 'Ironia e piedade', 'Olavo Bilac', 'Parnasianismo', '../obras/capas/ironia e piedade.png', 'Apresenta uma faceta mais humana e crítica de Bilac. A obra reúne poemas que mesclam sátira e compaixão, expondo as hipocrisias sociais, os valores morais duvidosos e as injustiças presentes na sociedade da época. O tom irônico serve como ferramenta de denúncia, enquanto a piedade revela uma sensibilidade crescente em relação às fragilidades humanas. Embora a estrutura formal continue obedecendo aos moldes parnasianos, o conteúdo aproxima-se de um espírito mais moderno, com traços pré-simbolistas e éticos. apresenta uma faceta mais humana e crítica de Bilac. A obra reúne poemas que mesclam sátira e compaixão, expondo as hipocrisias sociais, os valores morais duvidosos e as injustiças presentes na sociedade da época. O tom irônico serve como ferramenta de denúncia, enquanto a piedade revela uma sensibilidade crescente em relação às fragilidades humanas. Embora a estrutura formal continue obedecendo aos moldes parnasianos, o conteúdo aproxima-se de um espírito mais moderno, com traços pré-simbolistas e éticos.', 'http://www.dominiopublico.gov.br/pesquisa/DetalheObraDownload.do?select_action=&co_obra=43441&co_midia=2', NULL),
(268, 'Poesias infantis', 'Olavo Bilac', 'Parnasianismo', '../obras/capas/poesias infantis.png', 'Revela um lado pedagógico e lúdico de Bilac, voltado ao público infantil. São poemas simples, rimados e acessíveis, que tratam de temas como moral, civismo, natureza e educação. O autor adapta sua habilidade com a forma poética para uma linguagem clara e didática, mantendo a musicalidade e a métrica, mas sem a complexidade temática de suas outras obras. Trata-se de um projeto com forte intenção educativa, refletindo também o engajamento de Bilac com a causa do ensino e da formação cívica das crianças brasileiras.', NULL, NULL),
(269, 'Primeiros sonhos', 'Raimundo Correia', 'Parnasianismo', '../obras/capas/primeiros sonhos.png', 'Primeiros Sonhos é a obra de estreia de Cruz e Sousa, publicada ainda na adolescência. Trata-se de uma coletânea de poemas que revelam o início da sensibilidade poética do autor. Os textos são marcados por influências do Romantismo e do Parnasianismo, com linguagem lírica e emotiva, centrada em temas como a natureza, o amor idealizado e reflexões existenciais iniciais. Cruz e Sousa explora imagens suaves e sentimentais, típicas da juventude. A musicalidade dos versos já indica seu interesse pela harmonia das palavras. A obra prenuncia os elementos que ele desenvolveria no Simbolismo.', NULL, NULL),
(270, 'Sinfonias', 'Raimundo Correia', 'Parnasianismo', '../obras/capas/sinfonias.png', 'Sinfonias é uma obra de transição, em que Cruz e Sousa já começa a explorar aspectos mais musicais e sensoriais da linguagem, prefigurando o Simbolismo. A musicalidade dos versos e o uso de sinestesias sugerem uma tentativa de criar “música verbal”. Os poemas ainda mantêm estruturas clássicas, mas experimentam mais com ritmo e imagens poéticas. A presença de temas abstratos e espirituais se intensifica. O autor busca alcançar, por meio da poesia, uma dimensão mais elevada da arte. É uma obra que reflete seu amadurecimento estético e técnico.', NULL, NULL),
(271, 'Versos e versões', 'Raimundo Correia', 'Parnasianismo', '../obras/capas/versos e versoes.png', 'Essa obra reúne poemas próprios e traduções/adaptações de outros autores. Cruz e Sousa demonstra sua erudição e domínio da língua ao verter para o português poemas estrangeiros, imprimindo neles sua sensibilidade estética. Ao lado dos textos autorais, há um diálogo entre influências e criação original. A obra evidencia o contato do poeta com a literatura europeia. Mistura tradição e inovação, aproximando-se do simbolismo em conteúdo e forma. É uma etapa importante na construção de sua identidade poética.', NULL, NULL),
(272, 'Aleluias', 'Raimundo Correia', 'Parnasianismo', '../obras/capas/aleluias.png', 'Aleluias é uma coletânea em que Cruz e Sousa aprofunda sua religiosidade e espiritualidade, com versos carregados de misticismo, fé e exaltação. Os poemas apresentam um tom de louvor e esperança, em contraste com outras obras mais sombrias do autor. A musicalidade, o uso de símbolos e o conteúdo metafísico são características marcantes. A linguagem é elevada e marcada por um lirismo quase litúrgico. Há uma busca por transcendência e purificação da alma. O autor exalta o divino como refúgio e sentido para a existência.', NULL, NULL),
(274, 'Sonetos e Poemas', 'Alberto de Oliveira', 'Parnasianismo', '../obras/capas/sonetos e poemas.png', 'Sonetos e Poemas é uma das obras mais representativas de Alberto de Oliveira e do parnasianismo brasileiro. Nessa coletânea, o autor explora com grande rigor técnico a construção de sonetos e outras formas poéticas, evidenciando sua preocupação com a métrica perfeita, o vocabulário erudito e a impessoalidade temática. Os poemas abordam, em sua maioria, temas clássicos como a natureza idealizada, a arte pela arte e a exaltação da beleza estática, sempre com forte apelo visual. A obra reflete a fase de maturidade do poeta.', NULL, 1),
(275, 'Meridionais', 'Alberto de Oliveira', 'Parnasianismo', '../obras/capas/meridionais.png', 'Publicada um ano antes de Sonetos e Poemas, Meridionais já revela o domínio técnico e estético que marcaria a produção posterior de Alberto de Oliveira. A obra apresenta poemas que retratam a paisagem e a cultura do hemisfério sul, especialmente do Brasil, mantendo o controle emocional típico do parnasianismo e priorizando a forma e a harmonia dos versos.', NULL, 1);
INSERT INTO `obras` (`id`, `titulo`, `autor`, `escola_literaria`, `capa`, `descricao`, `arquivo`, `id_autor`) VALUES
(276, 'Versos e Rimas', 'Alberto de Oliveira', 'Parnasianismo', '../obras/capas/versos e rimas.png', 'Em Versos e Rimas, Alberto de Oliveira intensifica sua busca pela perfeição poética, reafirmando os princípios do parnasianismo. A coletânea se destaca pela musicalidade e pelo equilíbrio estrutural dos poemas, nos quais o autor refina ainda mais sua técnica no uso da métrica e das rimas ricas. Os temas variam entre a contemplação da arte, a descrição de objetos e cenas com riqueza de detalhes, e o distanciamento emocional do eu lírico. Trata-se de uma obra que demonstra não apenas habilidade formal, mas também maturidade estética.', NULL, 1),
(277, 'Poesias: Primeira Série', 'Alberto de Oliveira', 'Parnasianismo', '../obras/capas/poesias primeira serie.png', 'A Primeira Série da coletânea Poesias marca o início de uma fase em que Alberto de Oliveira reúne seus poemas em séries organizadas e revisadas pelo próprio autor. Esta primeira edição compila trabalhos de diferentes momentos de sua trajetória poética, oferecendo ao leitor uma visão ampla de sua evolução estética e técnica. Os poemas presentes mantêm o padrão formal elevado, típico do parnasianismo, e confirmam sua adesão aos princípios da arte refinada, do apuro linguístico e do rigor métrico. A série serve como uma antologia pessoal que preserva e consagra sua produção mais significativa.', NULL, 1),
(278, 'O Culto da Forma na Poesia Brasileira', 'Alberto de Oliveira', 'Parnasianismo', '../obras/capas/o culto da forma na poesia brasileira.png', 'Diferentemente das obras anteriores, O Culto da Forma na Poesia Brasileira é um ensaio crítico e teórico em que Alberto de Oliveira defende abertamente os fundamentos do parnasianismo. Neste texto, o autor argumenta que a verdadeira poesia está na forma perfeita, na escolha precisa das palavras e no uso rigoroso da métrica e da rima. Ele critica o subjetivismo romântico e valoriza o ideal clássico de equilíbrio e beleza. A obra funciona como um manifesto literário e um guia interpretativo de sua própria poesia, sendo essencial para entender sua visão artística e seu posicionamento dentro da literatura brasileira do final do século XIX e início do XX.', NULL, 1),
(279, 'Broquéis', 'Cruz e Sousa', 'Simbolismo', '../obras/capas/broqueis.png', 'Broquéis é a obra que marca oficialmente o início do Simbolismo no Brasil. Publicada em 1893, a coletânea reúne poemas em versos carregados de musicalidade, misticismo, sinestesia e simbolismo religioso. Cruz e Sousa explora temas como a dor existencial, o sofrimento, a busca pela transcendência e o conflito espiritual. A linguagem é rica, subjetiva e, por vezes, hermética, com destaque para o uso de imagens abstratas e sensoriais. A coletânea é marcada por uma linguagem inovadora e pelo uso intenso de símbolos e imagens sensoriais. É considerada um marco da modernidade poética no Brasil, rompendo com a rigidez do Parnasianismo.', 'http://www.dominiopublico.gov.br/pesquisa/DetalheObraDownload.do?select_action=&co_obra=16613&co_midia=2', 2),
(280, 'Missal', 'Cruz e Sousa', 'Simbolismo', '../obras/capas/missal.png', 'Publicado no mesmo ano de Broquéis, Missal é uma coletânea de poemas em prosa que reforça os elementos simbolistas presentes na obra de Cruz e Sousa. A escrita é altamente sensorial, com forte presença de sinestesias, imagens místicas e referências à espiritualidade. Os textos revelam uma busca estética e filosófica por aquilo que está além do material, refletindo angústias existenciais e o ideal de beleza. Os textos misturam lirismo e reflexão, criando atmosferas etéreas e introspectivas. A obra reforça o valor da intuição e da subjetividade como caminhos para a expressão artística.', 'http://www.dominiopublico.gov.br/pesquisa/DetalheObraDownload.do?select_action=&co_obra=16615&co_midia=2', 2),
(281, 'Últimos Sonetos', 'Cruz e Sousa', 'Simbolismo', '../obras/capas/ultimos sonetos.png', 'Últimos Sonetos é uma coletânea póstuma que reúne os últimos poemas escritos por Cruz e Sousa antes de sua morte. A obra é marcada por uma atmosfera profundamente melancólica, introspectiva e dolorosa. Os sonetos abordam temas como a morte, a solidão, a doença e a angústia da existência, revelando um eu lírico em estado de sofrimento físico e espiritual. A linguagem é simbólica, intensa e refinada, evidenciando o domínio técnico do poeta e a sensibilidade característica do simbolismo. Escritos em seus últimos anos de vida, revelam o sofrimento causado pela tuberculose e pela discriminação racial. São poemas confessionais, profundos e marcados pela visão trágica da existência.', 'http://www.dominiopublico.gov.br/pesquisa/DetalheObraDownload.do?select_action=&co_obra=16617&co_midia=2', 2),
(282, 'Evocações', 'Cruz e Sousa', 'Simbolismo', '../obras/capas/evocacoes.png', 'Evocações foi publicado após a morte do autor e reúne crônicas, ensaios e textos diversos em prosa poética. A obra traz reflexões sobre arte, literatura, religião e sentimentos humanos, sempre com o tom elevado e subjetivo típico do simbolismo. Apesar de menos conhecida que Broquéis e Missal, Evocações complementa o conjunto literário de Cruz e Sousa, revelando seu pensamento artístico e espiritual. A linguagem é expressiva, com forte apelo emocional e sensorial. A obra alterna momentos de sensibilidade com críticas sutis à sociedade de sua época. Mostra um Cruz e Sousa mais humano, dialogando com a arte e o cotidiano com delicadeza.', NULL, 2),
(283, 'Faróis', 'Cruz e Sousa', 'Simbolismo', '../obras/capas/farois.png', 'Faróis é uma coletânea póstuma que reúne ensaios, reflexões e críticas literárias de Cruz e Sousa. Diferente de suas obras mais poéticas, este livro evidencia seu pensamento crítico e intelectual. O autor discute temas ligados à estética, à literatura e à condição do artista, especialmente do artista negro no Brasil do século XIX. Apesar de ser uma obra em prosa, ainda traz traços do simbolismo em sua linguagem elaborada e sensível. A coletânea também denuncia o preconceito racial e social vivido pelo autor, expondo sua posição crítica diante da sociedade brasileira. Ao mesmo tempo, afirma o poder da arte como instrumento de luz e transformação.', 'http://www.dominiopublico.gov.br/pesquisa/DetalheObraDownload.do?select_action=&co_obra=16614&co_midia=2', 2),
(284, 'Ismália', 'Alphonsus de Guimaraens', 'Simbolismo', '../obras/capas/ismalia.png', 'Ismália é uma poesia lírica e simbolista que traz a idealização da mulher amada, muitas vezes vista como um ser puro e quase divino. A obra explora temas como o amor, a saudade e a morte, sempre imbuídos de um forte sentimento de melancolia e espiritualidade. A figura feminina aparece como uma espécie de guia para o poeta em sua busca pela transcendência. O poema reflete a influência do misticismo cristão e da tradição simbolista, valorizando a musicalidade e a linguagem carregada de símbolos. A atmosfera criada é etérea e introspectiva, convidando o leitor a uma experiência sensorial e emocional profunda. Ismália é uma expressão da dor da perda transformada em beleza e transcendência.', 'http://www.dominiopublico.gov.br/pesquisa/DetalheObraDownload.do?select_action=&co_obra=16526&co_midia=2', 3),
(285, 'Catedral', 'Alphonsus de Guimaraens', 'Simbolismo', '../obras/capas/catedral.png', 'Catedral é um poema em que Alphonsus expressa seu fascínio pelo sagrado e pela beleza arquitetônica das catedrais, símbolos da fé cristã. O texto evoca uma atmosfera de mistério e reverência, refletindo sobre a presença divina e a espiritualidade que emanam desses espaços religiosos. A obra combina elementos visuais e sonoros para criar uma experiência quase mística. O poema também simboliza a busca humana por um contato com o divino e a necessidade de um refúgio espiritual em meio ao sofrimento. A linguagem rica e a sensibilidade religiosa de Alphonsus tornam Catedral uma meditação poética sobre fé, esperança e transcendência.', NULL, 3),
(286, 'O Leito', 'Alphonsus de Guimaraens', 'Simbolismo', '../obras/capas/o leito.png', 'Em O Leito, o poeta aborda a morte de forma intimista, utilizando o leito como símbolo do descanso final e da passagem para o além. O poema mistura tristeza e resignação, enfatizando o aspecto espiritual da morte como libertação e reencontro com o divino. O tom é profundamente melancólico e reflexivo. A obra revela a influência da religiosidade na visão do poeta sobre a morte, que não é encarada apenas como fim, mas como transformação. A poesia convida o leitor a aceitar a finitude da vida com serenidade, encontrando na espiritualidade um sentido para o sofrimento.', NULL, 3),
(287, 'Setenário das Dores de Nossa Senhora', 'Alphonsus de Guimaraens', 'Simbolismo', '../obras/capas/setenario das dores de nossa senhora.png', 'Essa obra é uma sequência de poemas dedicados às sete dores da Virgem Maria, tema tradicional da religiosidade católica. Alphonsus une sua sensibilidade simbolista ao fervor religioso, explorando a dor, o sofrimento e a fé de Maria como modelo de entrega e sacrifício. O texto combina devoção com uma linguagem poética carregada de simbolismo e lirismo. O Setenário apresenta a Virgem como figura humana e divina, capaz de transmitir esperança e consolo diante do sofrimento humano. A obra destaca o papel do sofrimento na experiência espiritual e reforça o vínculo entre dor e redenção.', NULL, 3),
(288, 'Dona Mística', 'Alphonsus de Guimaraens', 'Simbolismo', '../obras/capas/dona mistica.png', 'Dona Mística é um poema longo que apresenta a figura de uma mulher idealizada, quase mística, que representa a pureza, a espiritualidade e o mistério da existência. A obra reflete sobre a presença do sagrado no cotidiano e a busca pela perfeição espiritual, típica da poesia simbolista. O texto é marcado por imagens etéreas e uma musicalidade delicada. Alphonsus constrói essa personagem como um símbolo da transcendência e da harmonia entre o mundo material e o espiritual. Dona Mística revela o desejo do poeta de superar o sofrimento terreno por meio da elevação da alma.', NULL, 3),
(289, 'Eu', 'Augusto dos Anjos', 'Simbolismo', '../obras/capas/eu.png', 'Único livro publicado em vida pelo autor, reunindo poemas sobre morte, degradação, angústia e solidão, com vocabulário científico e linguagem intensa.', 'http://www.dominiopublico.gov.br/pesquisa/DetalheObraDownload.do?select_action=&co_obra=2066&co_midia=2', 4),
(290, 'Outras Poesias', 'Augusto dos Anjos', 'Simbolismo', '../obras/capas/outras poesias.png', 'Outras Poesias reúne poemas que aprofundam o pessimismo e a visão crítica de Augusto dos Anjos sobre a vida e a condição humana. Os textos destacam a fragilidade do corpo, o sofrimento e a inevitabilidade da morte, expressos por meio de imagens fortes e metáforas impactantes. Essa coletânea complementa a temática presente em Eu, mostrando a coerência da sua linguagem única e sua busca por uma expressão poética autêntica e dolorosa. A obra reforça a relevância do poeta como precursor do Pré-modernismo e sua influência nas gerações seguintes.', 'http://www.dominiopublico.gov.br/pesquisa/DetalheObraDownload.do?select_action=&co_obra=1773&co_midia=2', 4),
(291, 'Psicologia de um Vencido', 'Augusto dos Anjos', 'Simbolismo', '../obras/capas/psicologia de um vencido.png', 'Em Psicologia de um Vencido, Augusto dos Anjos explora a dor e o desespero do ser humano diante da derrota e do fracasso. O poema reflete sobre a condição de alguém que se sente vencido pela vida, expressando sentimentos de amargura, resignação e angústia profunda. A obra é marcada pela intensidade emocional e pela crítica ao destino inevitável que assola o indivíduo, consolidando o tom existencialista do autor. Esse poema destaca a capacidade do poeta de traduzir a angústia universal em linguagem visceral e poderosa.', NULL, 4),
(292, 'Versos Íntimos', 'Augusto dos Anjos', 'Simbolismo', '../obras/capas/versos intimos.png', 'Versos Íntimos traz uma poesia introspectiva e sincera, onde o eu lírico revela seus conflitos internos, medos e sentimentos de solidão. Os poemas são permeados por um tom melancólico e reflexivo, expressando o sofrimento e a busca por sentido em meio à adversidade. A obra destaca a habilidade do poeta em combinar um vocabulário elaborado com uma profunda sensibilidade humana. Essa introspecção contribui para a universalidade dos sentimentos abordados, tornando-os atemporais e próximos do leitor.', NULL, 4),
(293, 'Ao Luar', 'Augusto dos Anjos', 'Simbolismo', '../obras/capas/ao luar.png', 'Ao Luar é um poema que contrapõe a beleza da natureza com o estado de angústia do poeta. A luz do luar, símbolo de serenidade e harmonia, serve como pano de fundo para as reflexões sombrias sobre a vida e a morte. A obra revela a dualidade entre o mundo externo e o universo interior do eu lírico, evidenciando a tensão entre a busca por paz e a inquietação existencial. Através desse contraste, Augusto dos Anjos reforça a fragilidade da condição humana diante do mistério da existência.', NULL, 4),
(294, 'Músicas', 'Emiliano Perneta', 'Simbolismo', '../obras/capas/musicas.png', 'Músicas é uma obra poética de Emiliano Perneta com forte influência parnasiana, explorando a musicalidade e a perfeição formal na construção dos poemas. O autor utiliza a música como metáfora para a harmonia estética, valorizando o ritmo, a sonoridade e a técnica na composição poética. Os poemas apresentam um estilo refinado, com ênfase na beleza e na descrição detalhada, características do parnasianismo, refletindo a busca pela perfeição artística. Ao mesmo tempo, a obra sugere uma visão romântica e idealizada da arte, como algo sublime e distante da realidade cotidiana. O autor também reflete sobre o poder da poesia como veículo para evocar emoções e sensações.', NULL, 5),
(295, 'Ilusão', 'Emiliano Perneta', 'Simbolismo', '../obras/capas/ilusao.png', 'Ilusão é um poema que aborda o tema do desengano e das falsas esperanças. A obra traz uma reflexão sobre as ilusões da vida e a transitoriedade da felicidade. Perneta utiliza um tom melancólico e introspectivo para mostrar como as expectativas humanas muitas vezes são frustradas, evidenciando o contraste entre os sonhos e a dura realidade. A obra revela um olhar crítico sobre a condição humana e suas limitações. O poeta também explora a efemeridade da vida e o sofrimento causado pela busca incessante por algo inalcançável, refletindo o descompasso entre o desejo e a realidade.', NULL, 5),
(296, 'A Vovozinha', 'Emiliano Perneta', 'Simbolismo', '../obras/capas/a vovozinha.png', 'A Vovozinha é uma poesia delicada que celebra a figura da avó, símbolo de ternura, sabedoria e carinho. Perneta descreve com sensibilidade a figura materna e a influência da avó no ambiente familiar, ressaltando suas qualidades amorosas e protetoras. O poema carrega um tom afetuoso e nostálgico, criando uma conexão emocional com o leitor ao retratar uma das relações mais tradicionais e afetuosas da vida familiar. A obra também remete a um ideal de simplicidade e harmonia, contrastando com a agitação da vida moderna. A imagem da avó representa o abrigo emocional e a continuidade das tradições familiares.', NULL, 5),
(297, 'Carta à Condessa D\'Eu', 'Emiliano Perneta', 'Simbolismo', '../obras/capas/carta a condessa deu.png', 'Carta à Condessa D\'Eu é uma obra que mistura poesia e prosa, sendo uma espécie de carta em que Perneta se dirige à condessa com uma escrita marcada pela formalidade e pelo refinamento estético. O autor utiliza a obra para expressar suas reflexões sobre a arte, a cultura e a sociedade, demonstrando sua visão crítica sobre temas políticos e sociais da época. A obra é também uma manifestação de seu engajamento literário e intelectual. Ao escrever com uma linguagem elaborada, Perneta faz uma crítica velada à sociedade aristocrática e aos valores predominantes, revelando seu posicionamento em relação à moral e à política da sua época.', NULL, 5),
(346, 'Sagarana', 'João Guimarães Rosa', 'Pós-Modernismo', '../obras/capas/sagarana.png', 'Sagarana é uma coletânea de contos que marca a estreia de João Guimarães Rosa no cenário literário nacional. A obra reúne oito narrativas que se passam no sertão mineiro, região que será central em boa parte de sua obra. Os contos exploram a vida e as relações humanas em uma realidade rural marcada pela dureza, pela violência e pela busca de sentido. Com uma linguagem inovadora, Rosa mistura o regionalismo com um estilo que busca reinventar a língua portuguesa, criando neologismos e utilizando expressões populares. Os personagens de Sagarana são figuras do sertão, como jagunços, vaqueiros e sertanejos, que vivem em ambientes repletos de conflitos existenciais e psicológicos, sempre imersos no contexto brutal e fascinante do interior do Brasil.', NULL, NULL),
(347, 'Grande Sertão: Veredas', 'João Guimarães Rosa', 'Pós-Modernismo', '../obras/capas/grande sertao veredas.png', 'Grande Sertão: Veredas é o romance mais famoso e a obra-prima de João Guimarães Rosa. Publicado em 1956, o livro narra a história de Riobaldo, um jagunço que percorre as veredas do sertão nordestino, refletindo sobre a vida, o amor, a morte e os conflitos internos entre o bem e o mal. O romance é narrado em primeira pessoa e apresenta uma linguagem rica, cheia de neologismos e metáforas, o que torna sua leitura desafiadora. Guimarães Rosa mistura elementos do realismo com o misticismo e a filosofia, criando um ambiente onde os conflitos morais e existenciais são explorados de forma profunda. O livro também é conhecido por seus diálogos e monólogos intensos, com uma narrativa que vai além da simples história de um jagunço, transformando-se em uma reflexão sobre a condição humana e as grandes questões da vida.', NULL, NULL),
(348, 'Campo Geral', 'João Guimarães Rosa', 'Pós-Modernismo', '../obras/capas/campo geral.png', 'Campo Geral é um romance de João Guimarães Rosa publicado em 1964. A obra narra a história de um jovem que retorna à sua terra natal, no interior de Minas Gerais, e encontra um cenário marcado pela saudade, pela solidão e pelos confrontos com o passado. O romance gira em torno das relações humanas no campo, explorando temas como a memória, a morte, a identidade e os laços familiares. Embora a obra tenha uma estrutura mais convencional que Grande Sertão: Veredas, ela já demonstra a linguagem rica e poética que caracterizaria o autor. Guimarães Rosa investiga, por meio de seus personagens, as complexidades da vida interiorana e os conflitos internos dos indivíduos diante da grandeza e da imensidão do sertão.', NULL, NULL),
(349, 'A Hora da Estrela', 'Clarice Lispector', 'Pós-Modernismo', '../obras/capas/a hora da estrela.png', 'Publicado em 1961, A Hora da Estrela narra a história de Macabéa, uma jovem nordestina que vive no Rio de Janeiro em extrema pobreza e alienação. O romance é escrito em primeira pessoa, com o narrador, Rodrigo S.M., se mostrando ao mesmo tempo envolvido e distanciado da vida da protagonista. A obra é uma reflexão sobre a existência e a solidão, revelando a vida de uma personagem invisível para a sociedade, com uma escrita introspectiva e cheia de angústia existencial. A autora, ao criar uma personagem marginalizada, levanta questões sobre a invisibilidade e o sofrimento silencioso das pessoas no mundo moderno.', NULL, NULL),
(350, 'Laços de Família', 'Clarice Lispector', 'Pós-Modernismo', '../obras/capas/lacos de familia.png', 'Publicado em 1960, Laços de Família é uma coletânea de contos que explora as relações familiares com uma profundidade psicológica característica de Clarice Lispector. A autora revela o interior dos personagens, mostrando os conflitos silenciosos e as tensões nas convivências familiares. Lispector investiga os sentimentos mais profundos, trazendo à tona uma sensibilidade incomum sobre as dinâmicas familiares e as complexidades do ser. Cada conto revela um momento de introspecção, mostrando as transformações internas dos personagens diante de pequenos eventos cotidianos.', NULL, NULL),
(351, 'A Paixão segundo G.H.', 'Clarice Lispector', 'Pós-Modernismo', '../obras/capas/a paixao segundo g.h.png', 'Publicado em 1964, A Paixão Segundo G.H. é um romance filosófico que segue G.H., uma mulher que, ao tentar limpar o quarto de uma empregada, vive uma experiência transformadora, questionando sua identidade e a existência. A narrativa é fragmentada e introspectiva, explorando o medo e a desconstrução do ser. A obra é uma investigação filosófica sobre a experiência humana e os limites da linguagem. Clarice utiliza a relação de G.H. com o mundo físico e o interior de sua mente para abordar questões de identidade e o sentido da vida.', NULL, NULL),
(352, 'Perto do Coração Selvagem', 'Clarice Lispector', 'Pós-Modernismo', '../obras/capas/perto do coracao selvagem.png', 'Publicado em 1943, Perto do Coração Selvagem segue a história de Joana, uma mulher marcada por um amor obsessivo e uma busca constante por sentido. A narrativa fragmentada acompanha os fluxos de consciência da protagonista, abordando temas como a solidão e o conflito entre o desejo e a repressão. O romance é uma reflexão sobre os limites da linguagem e da percepção. Joana, em sua busca por respostas, lida com as complexidades da psique humana, refletindo sobre seu próprio destino e a implacável necessidade de auto entendimento.', NULL, NULL),
(353, 'Água Viva', 'Clarice Lispector', 'Pós-Modernismo', '../obras/capas/agua viva.png', 'Publicado em 1973, Água Viva é um romance em que a protagonista reflete sobre sua vida, corpo e sua relação com a arte, usando uma linguagem poética e experimental. A narrativa flui como uma meditação sobre a transitoriedade da vida e o processo criativo. A obra é um convite à introspecção e à compreensão das complexidades internas do ser humano. A protagonista explora a natureza da arte como um reflexo de sua própria existência e a busca incessante por algo que não pode ser totalmente apreendido.', NULL, NULL),
(354, 'Os Sertões', 'Euclides da Cunha', 'Pré-Modernismo', '../obras/capas/os sertoes.png', 'Os Sertões é a obra-prima de Euclides da Cunha, considerada um marco na literatura brasileira e um estudo profundo sobre o Brasil. O livro trata da Guerra de Canudos (1896-1897), que ocorreu no interior da Bahia, e mistura história, sociologia, geografia e literatura. Em três partes, Euclides analisa a geografia e o povo sertanejo, as causas e o desenrolar da guerra e, finalmente, a destruição de Canudos. A obra também aborda as condições de vida e a resistência do sertanejo, destacando a relação entre o homem e a terra, e a questão da miséria e da violência. Os Sertões é uma crítica ao abandono do interior do Brasil e à desigualdade social.', 'http://www.dominiopublico.gov.br/pesquisa/DetalheObraDownload.do?select_action=&co_obra=16626&co_midia=2', NULL),
(355, 'Contrastes e Confrontos', 'Euclides da Cunha', 'Pré-Modernismo', '../obras/capas/contrastes e confrontos.png', 'Em Contrastes e Confrontos, Euclides da Cunha faz uma análise crítica das diferenças entre a sociedade urbana e rural no Brasil. O livro reflete sua preocupação com o processo de modernização do país, confrontando as condições de vida nas cidades com as do sertão. A obra discute a desigualdade social, a cultura e os desafios enfrentados pelas camadas populares, propondo uma reflexão sobre as contradições e os contrastes entre o Brasil moderno e o Brasil rural. É uma obra marcada por um olhar crítico e incisivo sobre as mudanças no país.', 'http://www.dominiopublico.gov.br/pesquisa/DetalheObraDownload.do?select_action=&co_obra=16625&co_midia=2', NULL),
(356, 'À Margem da História', 'Euclides da Cunha', 'Pré-Modernismo', '../obras/capas/a margem da historia.png', 'À Margem da História é uma obra em que Euclides da Cunha reflete sobre a história do Brasil e a formação da sua sociedade, discutindo os fatores que influenciaram o desenvolvimento da nação. O autor busca dar voz a aspectos marginalizados da história oficial, como os indígenas, os negros e os sertanejos. Ele questiona a narrativa dominante e propõe uma nova leitura sobre o Brasil, abordando temas como o colonialismo, as desigualdades e a construção de uma identidade nacional. O livro é uma tentativa de reescrever a história do país a partir de uma perspectiva mais inclusiva e crítica.', 'http://www.dominiopublico.gov.br/pesquisa/DetalheObraDownload.do?select_action=&co_obra=16624&co_midia=2', NULL),
(357, 'Canudos: Diário de uma Expedição', 'Euclides da Cunha', 'Pré-Modernismo', '../obras/capas/canudos diario de uma expedicao.png', 'Canudos: Diário de uma Expedição é uma obra mais íntima e pessoal de Euclides da Cunha, que relata sua experiência como parte da expedição militar que combateu os rebeldes de Canudos. O livro, publicado antes de Os Sertões, é um relato direto e detalhado sobre o cerco a Canudos, onde Euclides descreve o cenário de guerra, os personagens e as situações vividas durante a missão. A obra também reflete sobre as falhas do governo e as injustiças contra o povo sertanejo, aprofundando a visão crítica de Euclides sobre o processo de modernização do Brasil e a desumanização dos conflitos políticos.', 'http://www.dominiopublico.gov.br/pesquisa/DetalheObraDownload.do?select_action=&co_obra=18947&co_midia=2', NULL),
(358, 'Canaã', 'Graça Aranha', 'Pré-Modernismo', '../obras/capas/canaa.png', 'Canaã é a obra mais conhecida de Graça Aranha e um marco do Pré-modernismo brasileiro. O romance narra a história de um jovem intelectual europeu que viaja para o Brasil e se depara com os conflitos culturais entre os imigrantes europeus e a sociedade brasileira. A obra discute a identidade nacional brasileira, abordando temas como a formação do povo brasileiro e as diferentes influências culturais. A imigração europeia, especialmente a italiana, é central no romance, e Graça Aranha explora o impacto dessa imigração na sociedade brasileira, trazendo à tona dilemas de modernização e assimilação cultural.', NULL, NULL),
(359, 'A Estética da Vida', 'Graça Aranha', 'Pré-Modernismo', '../obras/capas/a estetica da vida.png', 'A Estética da Vida é um ensaio filosófico em que Graça Aranha reflete sobre a relação entre arte, vida e a busca pela beleza. A obra aborda questões sobre o papel da arte na sociedade e a visão do autor sobre a estética. Graça Aranha argumenta que a arte deve ser uma representação da realidade e, ao mesmo tempo, uma expressão de profundos sentimentos humanos. Ele discute a função da arte em diversos aspectos da vida, sendo um reflexo das emoções e das condições sociais. Este livro marca a tentativa do autor de relacionar a produção artística ao entendimento da vida.', NULL, NULL),
(360, 'Espírito Moderno', 'Graça Aranha', 'Pré-Modernismo', '../obras/capas/espirito moderno.png', 'Espírito Moderno apresenta uma análise do movimento modernista e a nova visão de mundo que estava emergindo no início do século XX. O autor reflete sobre as transformações culturais, sociais e artísticas que influenciavam o Brasil e o mundo. O livro examina a crise de valores e as novas correntes filosóficas e literárias, como o simbolismo e o impressionismo. A obra também discute o papel do artista no contexto da modernidade, propondo que a arte deve expressar as complexidades da vida moderna, longe das convenções do passado.', NULL, NULL),
(361, 'A Viagem Maravilhosa', 'Graça Aranha', 'Pré-Modernismo', '../obras/capas/a viagem maravilhosa.png', 'A Viagem Maravilhosa é uma narrativa simbólica em que Graça Aranha explora temas existenciais e filosóficos. O autor leva o leitor a uma jornada em que os personagens confrontam questões sobre a vida, o destino e o sentido da existência humana. A obra se insere no contexto da literatura de viagens, mas trata das transformações internas que ocorrem no ser humano ao enfrentar o desconhecido. Com uma linguagem poética e reflexiva, Graça Aranha propõe uma reflexão sobre o indivíduo em sua busca pela verdade e pelo entendimento do mundo.', NULL, NULL),
(362, 'Malazarte', 'Graça Aranha', 'Pré-Modernismo', '../obras/capas/malazarte.png', 'Malazarte mistura elementos de crítica social com a tradição literária. O livro narra a história de um personagem que representa a malícia, o cinismo e a astúcia humana. A obra trata da natureza do comportamento humano, abordando temas como a luta pelo poder, a falsidade e a busca pelos próprios interesses. Através de Malazarte, Aranha faz uma crítica à sociedade brasileira de sua época, desafiando as convenções e explorando as nuances da moralidade e da ética. A obra é uma reflexão sobre as contradições inerentes à condição social e política.', NULL, NULL),
(363, 'Reinações de Narizinho', 'Monteiro Lobato', 'Pré-Modernismo', '../obras/capas/reinacoes de narizinho.png', 'Reinações de Narizinho é o primeiro livro do universo fantástico criado por Monteiro Lobato no Sítio do Picapau Amarelo. A obra narra as aventuras de Narizinho, uma menina travessa e cheia de imaginação, que vive no sítio com a avó Dona Benta. Junto com seus amigos, como o boneco de pano Visconde de Sabugosa, o cachorro Rabicó e o sábio Doutor Caramujo, Narizinho vive uma série de histórias mágicas, que envolvem fadas, bruxas e personagens do folclore brasileiro. O livro é marcado pela fusão do real com o imaginário e introduz o leitor ao encantado mundo do Sítio do Picapau Amarelo.', NULL, NULL),
(364, 'Caçadas de Pedrinho', 'Monteiro Lobato', 'Pré-Modernismo', '../obras/capas/cacadas de pedrinho.png', 'Caçadas de Pedrinho é a sequência de Reinações de Narizinho e segue as aventuras do menino Pedrinho, que é corajoso e adora caçar animais com seu rifle. Neste livro, Pedrinho e seus amigos do sítio enfrentam vários desafios, incluindo a luta contra a onça, e acabam se envolvendo em situações mágicas, com personagens como a Cuca e a Narizinho, além de viagens ao mundo do folclore brasileiro. A obra combina o ambiente rural com elementos de fantasia, estimulando a imaginação das crianças, enquanto aborda temas de coragem, amizade e o respeito à natureza.', NULL, NULL),
(365, 'O Picapau Amarelo', 'Monteiro Lobato', 'Pré-Modernismo', '../obras/capas/o picapau amarelo.png', 'Em O Picapau Amarelo, Monteiro Lobato dá continuidade ao mundo fantástico do Sítio do Picapau Amarelo, apresentando novas aventuras com os personagens já conhecidos, como Dona Benta, Narizinho, Pedrinho, e o Saci. A obra reúne várias histórias interligadas, com personagens do folclore brasileiro, como o próprio Saci e a Cuca, e com a inclusão de novos elementos mágicos. A trama é centrada em situações e desafios enfrentados pelos personagens, muitos dos quais tentam resolver enigmas e mistérios em um mundo encantado. O livro mistura fantasia e crítica social de maneira lúdica e cativante.', NULL, NULL),
(366, 'Urupês', 'Monteiro Lobato', 'Pré-Modernismo', '../obras/capas/urupes.png', 'Urupês é uma obra de Monteiro Lobato que foge do universo infantil do Sítio do Picapau Amarelo e é voltada para o público adulto. O livro é uma coletânea de contos que retratam a vida do interior paulista, com uma visão crítica sobre a miséria, o atraso e as desigualdades sociais da época. A obra trata do cotidiano rural com um olhar mais realista e, por vezes, irônico. O protagonista de muitos contos é o típico homem do campo, com suas dificuldades, superstições e simplicidade, enquanto Monteiro Lobato faz uma crítica às estruturas sociais e políticas do Brasil.', NULL, NULL),
(367, 'Negrinha', 'Monteiro Lobato', 'Pré-Modernismo', '../obras/capas/negrinha.png', 'Negrinha é um conto de Monteiro Lobato que faz uma crítica social e aborda temas como a escravidão, a exploração e a discriminação racial. A história se passa em uma fazenda, onde a personagem-título, uma menina negra e órfã, é maltratada pelos donos da casa. O conto denuncia a crueldade e a desigualdade social, mostrando a vida difícil e a exploração sofrida pela protagonista. Apesar de sua curta extensão, a obra tem grande poder de crítica, expondo o preconceito e a opressão contra os negros na sociedade brasileira da época.', NULL, NULL),
(368, 'O Triste Fim de Policarpo Quaresma', 'Lima Barreto', 'Pré-Modernismo', '../obras/capas/o triste fim de policarpo quaresma.png', 'O Triste Fim de Policarpo Quaresma é um romance de Lima Barreto que satiriza o nacionalismo exacerbado e a ingenuidade do protagonista, Policarpo Quaresma. O personagem é um funcionário público que, obcecado por um amor idealizado pelo Brasil, tenta reformar o país com ideias simplistas e utópicas. Sua obsessão pelo nacionalismo o leva a uma série de desventuras e fracassos, refletindo a crítica do autor à situação política e social do Brasil na época. A obra é uma crítica ao patriotismo vazio, à burocracia e à falta de uma verdadeira consciência nacional, retratando a alienação de pessoas que se entregam a ideais sem base na realidade.', NULL, NULL),
(369, 'Clara dos Anjos', 'Lima Barreto', 'Pré-Modernismo', '../obras/capas/clara dos anjos.png', 'Clara dos Anjos é um romance de Lima Barreto que aborda questões de classe social, sexo e moralidade. A história é centrada em Clara, uma jovem de classe média que, ao ser seduzida por um homem de aparência respeitável, acaba engravidando e sendo desamparada pela sociedade. O romance explora a hipocrisia da moral burguesa e o destino das mulheres que, em sua época, não tinham autonomia ou voz. Clara dos Anjos, além de ser um retrato da sociedade carioca do início do século XX, também é uma análise das relações de poder e da desigualdade de gênero. A obra denuncia as contradições do Brasil em relação à ética e à moral.', NULL, NULL),
(370, 'Recordações do Escrivão Isaías Caminha', 'Lima Barreto', 'Pré-Modernismo', '../obras/capas/recordacoes do escrivao isaias caminhados.png', 'Recordações do Escrivão Isaías Caminha é um romance de Lima Barreto que se passa no Rio de Janeiro e narra a trajetória de Isaías Caminha, um jovem que, ao buscar um lugar na sociedade carioca, enfrenta as dificuldades de um sistema social marcado pela corrupção, pelas injustiças e pelas desigualdades. Através da experiência de Isaías, Lima Barreto critica a classe média urbana, a falsidade social e o elitismo, mostrando como o personagem é moldado pela sociedade que o marginaliza. A obra é um retrato de uma juventude frustrada, que tenta se inserir em um sistema corrupto e desumano, mas que acaba sendo destruída por ele.', NULL, NULL),
(371, 'Cemitério dos Vivos', 'Lima Barreto', 'Pré-Modernismo', '../obras/capas/cemiterio dos vivos.png', 'O Cemitério dos Vivos é um romance de Lima Barreto que, por meio de uma narrativa de ficção, analisa as condições de vida e a repressão social que o protagonista sofre. O livro se passa em um contexto em que a personagem principal, mentalmente perturbada e diagnosticada com uma doença psíquica, tenta sobreviver em uma sociedade que o marginaliza. A obra é uma crítica direta ao abandono dos doentes mentais e à falta de uma estrutura de cuidado e compreensão para com os indivíduos considerados \"diferentes\". Lima Barreto denuncia as falhas do sistema de saúde mental da época e reflete sobre as condições de vida que tornam certos indivíduos \"vivos, mas mortos\" para a sociedade.', NULL, NULL),
(372, 'Vida e Morte de M.J. Gonzaga de Sá', 'Lima Barreto', 'Pré-Modernismo', '../obras/capas/vida e morte de m.j. gonzaga de sados vivos.png', 'Vida e Morte de M.J. Gonzaga de Sá é uma narrativa que mistura o romance psicológico com a crítica social. A obra narra a vida de M.J. Gonzaga de Sá, um homem de classe média que, devido a suas ações e decisões ao longo de sua vida, acaba se afastando dos valores morais e sociais da época. A história aborda temas como a corrupção moral, o egoísmo e a decadência da sociedade brasileira, refletindo a degradação do protagonista à medida que se distancia de seus princípios. A obra é uma crítica ao individualismo e à hipocrisia das instituições sociais, como a política, a religião e as famílias tradicionais.', NULL, NULL),
(373, 'Alguma Poesia', 'Carlos Drummond de Andrade', 'Modernismo', '../obras/capas/alguma poesia.png', 'Publicado em 1930, Alguma Poesia é o primeiro livro de Drummond e marca sua entrada na literatura brasileira. A obra mistura o lirismo modernista com um olhar crítico sobre a realidade social e política do Brasil. Drummond aborda temas como a solidão, o sofrimento, as injustiças sociais e a busca por uma linguagem poética mais livre e expressiva. A poética da obra explora a ambiguidade entre a beleza e a dor, a percepção do cotidiano e a busca por um sentido maior. Além disso, a sua escrita reflete a tensão entre o subjetivo e o coletivo, características do movimento modernista.', NULL, NULL);
INSERT INTO `obras` (`id`, `titulo`, `autor`, `escola_literaria`, `capa`, `descricao`, `arquivo`, `id_autor`) VALUES
(374, 'A Rosa do Povo', 'Carlos Drummond de Andrade', 'Modernismo', '../obras/capas/a rosa do povo.png', 'Publicado em 1945, A Rosa do Povo é uma reflexão sobre o contexto da Segunda Guerra Mundial e os problemas sociais do Brasil. A obra traz uma poesia crítica, tratando da opressão, da alienação e da necessidade de resistência. A \"rosa\" é um símbolo de beleza e luta em tempos difíceis. A obra reflete o sofrimento de um povo que, apesar de suas dificuldades, tenta encontrar formas de resistir à opressão política e à desigualdade social. A poesia é marcada por um tom de dor, mas também de esperança, sugerindo que a arte pode ser uma arma contra a crueldade do mundo.', NULL, NULL),
(375, 'Sentimento do Mundo', 'Carlos Drummond de Andrade', 'Modernismo', '../obras/capas/sentimento do mundo.png', 'Lançado em 1940, Sentimento do Mundo é uma obra melancólica que lida com o sofrimento humano e o vazio existencial durante a Segunda Guerra Mundial. Drummond reflete sobre as incertezas da vida, as contradições da modernidade e o sentimento de desamparo diante da crueldade do mundo. A obra é permeada por um sentimento de angústia existencial, mas também de solidariedade com os outros. Drummond questiona o lugar do homem em um mundo cheio de destruição, enquanto reflete sobre os dilemas éticos e sociais que o afligem. A linguagem é intimista, mas com uma forte crítica à realidade política e humana.', NULL, NULL),
(376, 'Claro Enigma', 'Carlos Drummond de Andrade', 'Modernismo', '../obras/capas/claro enigmado mundo.png', 'Publicado em 1951, Claro Enigma busca compreender os grandes mistérios da vida e da existência. A poesia de Drummond mistura clareza e ambiguidade, explorando questões existenciais de maneira filosófica, com uma linguagem profunda e complexa. O livro revela um poeta em busca de respostas para os enigmas da vida, que, apesar de oferecerem fragmentos de revelação, permanecem impenetráveis. Ao mesmo tempo, o poeta reflete sobre as incertezas do ser e a impossibilidade de compreensão total. A obra também lida com a condição humana, a relação do indivíduo com o mundo e com o próprio tempo.', NULL, NULL),
(377, 'O Quinze', 'Rachel de Queiroz', 'Modernismo', '../obras/capas/o quinze.png', '\"O Quinze\" é um romance de Rachel de Queiroz publicado em 1930, que descreve a grande seca de 1915 no Nordeste do Brasil, também conhecida como \"A Seca de 1915\". A obra apresenta a luta pela sobrevivência de pessoas que vivem no sertão nordestino, mostrando o impacto devastador da seca na vida dos sertanejos. A narrativa acompanha personagens como Vicente, uma figura que busca ajuda para salvar sua família, e outras pessoas que enfrentam a fome e a miséria. O livro é uma denúncia das condições de vida no sertão e da indiferença do governo para com a população nordestina.', NULL, NULL),
(378, 'Caminho de Pedras', 'Rachel de Queiroz', 'Modernismo', '../obras/capas/caminho de pedras.png', 'Caminho de Pedras é o primeiro romance de Rachel de Queiroz, publicado em 1937. A obra retrata a vida no sertão nordestino, onde a seca e a pobreza impõem enormes dificuldades aos habitantes. O protagonista, João Camilo, luta para sobreviver após perder sua terra e sua família. A história aborda as dificuldades do povo nordestino, a falta de apoio governamental e a resistência das pessoas diante da adversidade. Com uma narrativa realista, a autora denuncia a desigualdade social e a negligência do poder público, enquanto destaca a força e a determinação do povo sertanejo.', NULL, NULL),
(379, 'João Miguel', 'Rachel de Queiroz', 'Modernismo', '../obras/capas/joao miguel.png', 'João Miguel, de Rachel de Queiroz, publicado em 1942, é um romance que se passa no sertão nordestino e narra a história de João Miguel, um jovem que enfrenta as dificuldades da vida rural e as adversidades de sua região. A obra aborda temas como a luta pela sobrevivência, as relações familiares e a busca por identidade. João Miguel busca compreender seu lugar no mundo enquanto lida com os desafios impostos pela pobreza e pelas injustiças sociais. O romance é uma crítica às desigualdades sociais e ao modo de vida do sertão, destacando a força e a resistência do povo nordestino diante das dificuldades da vida no campo.', NULL, NULL),
(380, 'As Três Marias', 'Rachel de Queiroz', 'Modernismo', '../obras/capas/as tres marias.png', '\"As Três Marias\", publicado em 1939, é um romance da escritora Rachel de Queiroz, que explora a vida de três mulheres, Marias, no contexto da sociedade brasileira da época. Cada uma das protagonistas enfrenta desafios e dilemas diferentes, representando as várias faces do universo feminino, como a questão da liberdade, do casamento, e da luta pela independência. O livro é um estudo sobre as condições das mulheres da época, abordando temas como a repressão social e a busca por identidade e autossuficiência.', NULL, NULL),
(381, 'Memorial de Maria Moura', 'Rachel de Queiroz', 'Modernismo', '../obras/capas/memorial de maria moura.png', '\"Memorial de Maria Moura\", lançado em 1992, é um romance histórico e de forte carga emocional, também de Rachel de Queiroz. Ele conta a história de Maria Moura, uma mulher sertaneja que, desde sua infância, vive uma série de desafios e tragédias em um Brasil rural e violento. A narrativa é construída como um memorial, onde a protagonista conta sua própria história, suas lutas, conquistas, amores e dores. A obra é uma reflexão sobre o papel das mulheres no sertão nordestino e uma crítica à sociedade patriarcal e às desigualdades sociais.', NULL, NULL),
(382, 'Capitães da Areia', 'Jorge Amado', 'Modernismo', '../obras/capas/capitaes da areia.png', 'Publicado em 1937, Capitães da Areia descreve a vida de um grupo de meninos de rua em Salvador, conhecidos como \"capitães da areia\". O protagonista, Pedro Bala, lidera o grupo em uma luta pela sobrevivência em meio à pobreza e violência. A obra é uma crítica social à desigualdade e ao abandono dos pobres, abordando a amizade e lealdade entre os meninos. Amado apresenta a realidade das ruas e os sonhos que, apesar das adversidades, persistem.', NULL, NULL),
(383, 'Gabriela, Cravo e Canela', 'Jorge Amado', 'Modernismo', '../obras/capas/gabriela, cravo e canelada.png', 'Publicado em 1958, Gabriela, Cravo e Canela mistura erotismo, política e uma rica descrição da sociedade baiana na década de 1920. A obra conta a história de Gabriela, uma mulher sensual, e de Nacib, um comerciante que se apaixona por ela. O romance também aborda as tensões entre as forças conservadoras e as mudanças sociais. Amado explora as complexas relações entre desejo, poder e identidade cultural em Ilhéus.', NULL, NULL),
(384, 'Dona Flor e Seus Dois Maridos', 'Jorge Amado', 'Modernismo', '../obras/capas/dona flor e seus dois maridos.png', 'Publicado em 1966, Dona Flor e Seus Dois Maridos mistura comédia romântica e realismo mágico. Dona Flor, viúva de Vadinho, um homem boêmio, se casa com Teodoro, um farmacêutico sério. Quando Vadinho retorna do além, ele interfere no novo casamento. A obra reflete sobre o equilíbrio entre prazer e razão, enquanto Dona Flor lida com seus conflitos internos e a sobreposição do passado e presente.', NULL, NULL),
(385, 'Mar Morto', 'Jorge Amado', 'Modernismo', '../obras/capas/mar morto.png', 'Publicado em 1936, Mar Morto explora as relações entre os trabalhadores do cais e o mar, com foco nas personagens das cidades portuárias da Bahia. O romance segue o romance entre João de Adão e Maria, enquanto lida com a exploração e os conflitos de classe. O mar, simbólico na narrativa, representa tanto a liberdade quanto a opressão. Amado faz uma crítica ao sistema colonial e à busca de identidade.', NULL, NULL),
(386, 'Tenda dos Milagres', 'Jorge Amado', 'Modernismo', '../obras/capas/tenda dos milagres.png', 'Publicado em 1969, Tenda dos Milagres narra a história de Pedro Archanjo, um intelectual afro-brasileiro que luta contra o racismo e a opressão. A obra mistura elementos da cultura afro-brasileira com crítica social ao Brasil pós-abolição. Pedro busca recuperar as raízes culturais dos negros no Brasil, explorando identidade, ancestralidade e resistência. A \"tenda dos milagres\" é o espaço onde a tradição e a cultura afro-brasileira se manifestam como formas de resistência.', NULL, NULL),
(387, 'Macunaíma', 'Mário de Andrade', 'Modernismo', '../obras/capas/macunaina.png', 'Publicado em 1928, Macunaíma é um romance modernista que mistura mitologia, folclore e crítica social. O protagonista, Macunaíma, é um herói sem caráter, que vive várias aventuras, transitando entre o Brasil e o universo mitológico. A obra explora a identidade brasileira de maneira irreverente, com uma linguagem experimental e cheia de humor, ironizando os aspectos da cultura nacional. Mário de Andrade usa a figura de Macunaíma para questionar os estereótipos do \"herói nacional\" e refletir sobre a construção da identidade do país.', NULL, NULL),
(388, 'Pauliceia Desvairada', 'Mário de Andrade', 'Modernismo', '../obras/capas/iracema.png', 'Publicado em 1922, Pauliceia Desvairada é o primeiro livro de poesias modernistas de Mário de Andrade. A obra é uma celebração e uma crítica à cidade de São Paulo, retratando sua modernidade, caos urbano e contraditórios. Com uma linguagem desafiadora, Andrade abandona a métrica e a rima tradicionais, criando uma poesia mais livre e sensorial. A obra reflete sobre a busca pela identidade nacional, a transformação da sociedade e a exploração dos sentidos na cidade moderna.', NULL, NULL),
(389, 'Contos Novos', 'Mário de Andrade', 'Modernismo', '../obras/capas/contos novos.png', 'Publicado em 1958, Contos Novos é uma coleção de histórias que explora as complexidades da alma humana e suas contradições. Clarice Lispector revela personagens em momentos de crise existencial e reflexão sobre suas vidas cotidianas. A obra mantém a marca da autora: uma escrita introspectiva e profunda, que explora o que está além da superfície das relações e sentimentos humanos. Os contos são como pequenas meditações sobre o ser, o tempo e o desconhecido dentro de cada pessoa.', NULL, NULL),
(390, 'Amar, Verbo Intransitivo', 'Mário de Andrade', 'Modernismo', '../obras/capas/amar, verbo intransitivo.png', 'Publicado em 1927, Amar, Verbo Intransitivo é um romance que explora a sexualidade e os dilemas do amor. A obra segue a história de um jovem, Sérgio, que vive um intenso relacionamento com uma mulher misteriosa, e lida com os conflitos internos e as descobertas sobre si mesmo. A narrativa apresenta uma crítica à moralidade da época, abordando temas como a repressão e a liberdade sexual. O livro também investiga o conceito de amor de maneira desafiadora, ao colocar em questão os padrões tradicionais de sentimento e relacionamento.', NULL, NULL),
(391, 'Angústia', 'Graciliano Ramos', 'Modernismo', '../obras/capas/angustia.png', 'Publicado em 1936, Angústia é um romance psicológico que narra a crise existencial de Luis da Silva, um homem que vive em uma cidade pequena do interior. A obra descreve sua luta interna, suas paranoias e o sentimento de incompletude, refletindo sobre os dilemas da subjetividade humana. A escrita de Graciliano é densa e introspectiva, explorando a angústia de um personagem que tenta entender sua vida e suas relações com os outros. O romance é uma crítica à repressão social e à falta de comunicação entre os indivíduos.', NULL, NULL),
(392, 'Vidas Secas', 'Graciliano Ramos', 'Modernismo', '../obras/capas/vidas secas.png', 'Publicado em 1938, Vidas Secas é um romance que retrata a dura realidade dos sertanejos nordestinos em meio à seca e à miséria. A história segue a vida de uma família de retirantes, especialmente de Fabiano, um homem simples e rude, e de sua esposa, Sinha Vitória, enquanto lutam para sobreviver em um ambiente implacável. A obra aborda temas como a opressão, a luta pela sobrevivência e a falta de perspectivas, em uma crítica à estrutura social e ao abandono dos mais pobres. Graciliano apresenta uma narrativa seca e objetiva, com um profundo olhar sobre a tragédia humana.', NULL, NULL),
(393, 'Infância', 'Graciliano Ramos', 'Modernismo', '../obras/capas/infancia.png', 'Publicado em 1945, Infância é uma obra de memórias de Graciliano Ramos, na qual ele relembra sua juventude no interior de Alagoas. O livro narra episódios marcantes da infância do autor, descrevendo o ambiente social, econômico e cultural da época. A narrativa é permeada por reflexões sobre a formação do caráter, as dificuldades da vida e a influência do meio na construção da identidade.', NULL, NULL),
(394, 'A Obscena Senhora D', 'Hilda Hilst', 'Pós-Modernismo', '../obras/capas/a obscena senhora d.png', 'Publicado em 1982, este romance em fluxo de consciência acompanha Hillé, uma mulher reclusa que reflete sobre a morte, o amor, a solidão e o sentido da existência humana. A obra é marcada pelo experimentalismo linguístico e pela intensidade poética, desafiando convenções narrativas e mergulhando profundamente na subjetividade da personagem.', NULL, NULL),
(395, 'Com Meu Olhar de Cão', 'Hilda Hilst', 'Pós-Modernismo', '../obras/capas/com meu olhar de cao.png', 'Lançado em 1986, este livro reúne contos curtos que exploram temas como desejo, morte, espiritualidade e a busca pelo sentido da vida. A prosa fragmentada e lírica revela a maestria da autora em mesclar poesia e narrativa, criando atmosferas simbólicas e ambíguas.', NULL, NULL),
(396, 'Do Desejo', 'Hilda Hilst', 'Pós-Modernismo', '../obras/capas/do desejo.png', 'Publicada em 1992, esta coletânea de poemas aborda o amor, o corpo, a transcendência e a criação artística. Com forte carga erótica e espiritual, a obra sintetiza a tensão entre carne e espírito, marcando a escrita da autora com versos densos e sensuais.', NULL, NULL),
(397, 'Júbilo, Memória, Noviciado da Paixão', 'Hilda Hilst', 'Pós-Modernismo', '../obras/capas/jubilo, memoria, noviciado da paixaosejo.png', 'Lançado em 1974, este livro de poesia é um dos mais estudados da autora, reunindo versos densos e líricos que exploram misticismo, erotismo e a condição humana. É fundamental para compreender a fase mais espiritual da escritora.', NULL, NULL),
(398, 'Cantares de Perda e Predileção', 'Hilda Hilst', 'Pós-Modernismo', '../obras/capas/cantares de perda e predilecao.png', 'Publicado em 1983, este livro de poesia é dividido em três partes que abordam o amor, a perda e a passagem do tempo. Sua linguagem musical e imagética reforça o prestígio da autora como uma das maiores poetas brasileiras.', NULL, NULL),
(399, 'Sono', 'João Cabral de Melo Neto', 'Pós-Modernismo', '../obras/capas/sono.png', 'O poema Sono já anuncia a marca de João Cabral de Melo Neto: uma poesia objetiva, enxuta e racional. Nele, o sono é representado como um estado de perda de consciência e de controle, algo que o eu lírico rejeita, preferindo a vigília e a lucidez. A recusa ao devaneio onírico mostra a postura crítica do poeta, que associa a criação literária ao trabalho consciente e ao rigor da linguagem, e não à inspiração passiva ou ao abandono da razão.', NULL, NULL),
(400, 'Morte e Vida Severina', 'João Cabral de Melo Neto', 'Pós-Modernismo', '../obras/capas/morte e vida severina.png', 'Considerada a obra-prima de João Cabral, Morte e Vida Severina é um auto de natal pernambucano que retrata a trajetória de Severino, um retirante nordestino em busca de melhores condições de vida. O título sintetiza o enredo: a vida do sertanejo é severina, marcada pela pobreza, pela fome, pela seca e pela constante presença da morte. A narrativa culmina no nascimento de uma criança, que, mesmo pobre, simboliza a esperança de renovação da vida. O texto combina elementos regionais com uma dimensão universal, tratando da dignidade humana diante da adversidade.', NULL, NULL),
(401, 'O Engenheiro', 'João Cabral de Melo Neto', 'Pós-Modernismo', '../obras/capas/o engenheiro.png', 'Primeiro livro publicado por João Cabral, O Engenheiro apresenta a concepção do poeta sobre a própria poesia. O engenheiro simboliza o escritor que constrói o poema com técnica, esforço e precisão, como quem ergue um edifício. A obra rompe com a tradição lírica subjetiva e sentimental, valorizando a objetividade, a racionalidade e a exatidão das palavras. Assim, desde sua estreia, João Cabral mostra seu estilo característico: uma poesia feita de cálculo e rigor, não de improviso ou emoção descontrolada.', NULL, NULL),
(402, 'O Cão sem Plumas', 'João Cabral de Melo Neto', 'Pós-Modernismo', '../obras/capas/o cao sem plumas.png', 'Nesse longo poema, João Cabral descreve o Recife e o Rio Capibaribe como metáforas da miséria nordestina. O “cão sem plumas” é a imagem escolhida para representar o homem pobre da região, despido de tudo, marcado pela exploração, pela fome e pela degradação social. A linguagem é direta, seca e visual, transformando o espaço urbano em reflexo das condições humanas. É uma das obras em que o autor mais intensamente une crítica social e força poética, consolidando sua visão engajada da literatura.', NULL, NULL),
(403, 'Escola das Facas', 'João Cabral de Melo Neto', 'Pós-Modernismo', '../obras/capas/escola das facas.png', 'Já em sua fase madura, João Cabral publica Escola das Facas, obra em que retoma sua poesia marcada pela objetividade e pela crítica da realidade. A metáfora das “facas” indica a dureza da vida, a necessidade de resistência e de enfrentamento diante das dificuldades. O livro revisita temas recorrentes de sua obra, como o sertão, a luta, a morte e a sobrevivência, mas agora com a maturidade de um poeta plenamente consciente de sua voz. Mantém-se a linguagem cortante, enxuta e rigorosa, reafirmando seu estilo único dentro da literatura brasileira.', NULL, NULL),
(404, 'Os Sermões', 'Padre Antônio Vieira', 'Barroco', '../obras/capas/ossermoes.png', 'De temática religiosa, o Sermão da Sexagésima é uma prosa sacra que tem o intuito de convencer as pessoas a se converterem à religião católica. Dessa forma, Vieira utiliza diversas passagens da Bíblia para escrever os sermões. Menciona temas como Deus, os homens, o pregador e o evangelho. \n\nAssim, ele tenta mostrar que a culpa é do pregador e da veracidade de sua doutrina. Ele critica, portanto, outros pregadores e a ineficácia de seus discursos. \n\nEm resumo, o Sermão da Sexagésima foca na própria forma de fazer sermões. O Padre usa da metalinguagem para apresentar sua ideia central: pregar é semear', 'https://www.dominiopublico.gov.br/pesquisa/DetalheObraDownload.do?select_action=&co_obra=1745&co_midia=2', NULL);
