-- =============================================================
--  Fólio — banco de dados
--
--  Como importar:
--    phpMyAdmin > Importar > selecione este arquivo > Executar
--  ou pelo terminal:
--    mysql -u root < database/folio.sql
--
--  Cria o banco `literatura` com a estrutura completa e o acervo
--  (autores e obras). Não contém usuários nem postagens do fórum.
-- =============================================================

SET SQL_MODE = "NO_AUTO_VALUE_ON_ZERO";
SET NAMES utf8mb4;

CREATE DATABASE IF NOT EXISTS `literatura` DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci;
USE `literatura`;

SET FOREIGN_KEY_CHECKS = 0;
DROP TABLE IF EXISTS `votos_topicos`, `respostas`, `topicos`, `usuarios`, `obras`, `autores`;
SET FOREIGN_KEY_CHECKS = 1;

-- -------------------------------------------------------------
-- Acervo
-- -------------------------------------------------------------

CREATE TABLE `autores` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `nome` varchar(100) NOT NULL,
  `biografia` text DEFAULT NULL,
  `escola_literaria` varchar(255) DEFAULT NULL,
  `capa` varchar(255) DEFAULT NULL COMMENT 'Foto do autor',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE `obras` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `titulo` varchar(255) NOT NULL,
  `autor` varchar(255) NOT NULL,
  `escola_literaria` varchar(100) DEFAULT NULL,
  `capa` varchar(255) DEFAULT NULL,
  `descricao` text DEFAULT NULL,
  `arquivo` varchar(255) DEFAULT NULL COMMENT 'Link de download no Domínio Público',
  `id_autor` int(11) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `fk_autor` (`id_autor`),
  CONSTRAINT `fk_autor` FOREIGN KEY (`id_autor`) REFERENCES `autores` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- -------------------------------------------------------------
-- Usuários e fórum
-- (ON DELETE CASCADE: ao excluir uma conta, seus tópicos,
--  respostas e votos são removidos junto)
-- -------------------------------------------------------------

CREATE TABLE `usuarios` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `nome` varchar(100) DEFAULT NULL,
  `username` varchar(100) NOT NULL,
  `email` varchar(100) NOT NULL,
  `senha` varchar(255) NOT NULL,
  `bio` text DEFAULT NULL,
  `localizacao` varchar(100) DEFAULT NULL,
  `foto` varchar(255) DEFAULT NULL,
  `data_cadastro` timestamp NOT NULL DEFAULT current_timestamp(),
  `token_recuperacao` varchar(255) DEFAULT NULL,
  `token_expira` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `email` (`email`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE `topicos` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `usuario_id` int(11) NOT NULL,
  `titulo` varchar(255) NOT NULL,
  `conteudo` text NOT NULL,
  `data_criacao` datetime DEFAULT current_timestamp(),
  `estrelas` int(11) DEFAULT 0 COMMENT 'Média arredondada dos votos',
  `obra_relacionada` varchar(255) NOT NULL DEFAULT '',
  PRIMARY KEY (`id`),
  KEY `usuario_id` (`usuario_id`),
  CONSTRAINT `topicos_ibfk_1` FOREIGN KEY (`usuario_id`) REFERENCES `usuarios` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE `respostas` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `topico_id` int(11) NOT NULL,
  `usuario_id` int(11) NOT NULL,
  `conteudo` text NOT NULL,
  `data_criacao` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `topico_id` (`topico_id`),
  KEY `usuario_id` (`usuario_id`),
  CONSTRAINT `respostas_ibfk_1` FOREIGN KEY (`topico_id`) REFERENCES `topicos` (`id`) ON DELETE CASCADE,
  CONSTRAINT `respostas_ibfk_2` FOREIGN KEY (`usuario_id`) REFERENCES `usuarios` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE `votos_topicos` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `usuario_id` int(11) NOT NULL,
  `topico_id` int(11) NOT NULL,
  `estrelas` int(11) NOT NULL,
  `data_voto` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `usuario_topico` (`usuario_id`,`topico_id`),
  KEY `topico_id` (`topico_id`),
  CONSTRAINT `votos_ibfk_1` FOREIGN KEY (`usuario_id`) REFERENCES `usuarios` (`id`) ON DELETE CASCADE,
  CONSTRAINT `votos_ibfk_2` FOREIGN KEY (`topico_id`) REFERENCES `topicos` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- -------------------------------------------------------------
-- Dados do acervo
-- -------------------------------------------------------------



Escrivão da frota de Pedro Álvares Cabral, Caminha enviou a carta para o rei D. Manuel I (1469-1521) para comunicar o descobrimento das novas terras. Datada de Porto Seguro (no litoral sul baiano da atual de acordo com Francisco Adolfo de Varnhagen), no dia 1 de maio de 1500, foi levada a Portugal por Gaspar de Lemos, comandante do navio de mantimentos da frota.', 'http://www.dominiopublico.gov.br/pesquisa/DetalheObraDownload.do?select_action=&co_obra=17424&co_midia=2', NULL),
(2, 'Duas Viagens ao Brasil', 'Hans Staden', 'Quinhentismo', '../obras/capas/duas viagens ao brasil.png', 'Duas vezes em meados do século XVI, o mercenário e arcabuzeiro alemão Hans Staden (1525 -1576) aportou nas costas do recém-descoberto Brasil. A primeira, em 1549, passando por Pernambuco e pela Paraíba, e a segunda, em 1550, quando chegou na ilha de Santa Catarina. Na segunda viagem foi preso pelo governador-geral e em seguida capturado pelos índios tamoios. O jovem Staden viveu para contar o que viu - paisagens virgens, riquezas inexploradas e a prática ritual do canibalismo, do qual por muito pouco não foi vítima. O livro com o seu relato foi publicado em 1557, em Marburgo, Alemanha, ilustrado por xilogravuras anônimas baseadas nas suas descrições.', NULL, NULL),
(3, 'Feitos de Mem de Sá', 'Padre José de Anchieta', 'Quinhentismo', '../obras/capas/dos grandes feitos de mem de sa.png', '"Feitos de Mem de Sá" é uma obra de José de Anchieta, um dos mais importantes jesuítas e escritores do Brasil colonial. Anchieta, conhecido por sua contribuição à catequese indígena e à literatura brasileira, escreveu várias obras que combinam história, religião e moral. A obra narra os feitos de Mem de Sá, que foi o terceiro Governador-Geral do Brasil, servindo de 1557 a 1572. Mem de Sá é lembrado por seu papel crucial na consolidação da presença portuguesa no Brasil e na defesa contra invasões estrangeiras, especialmente a francesa. Ele é conhecido por ter liderado a expedição que expulsou os franceses do Rio de Janeiro e por seu trabalho na organização do território colonial.', 'http://www.dominiopublico.gov.br/pesquisa/DetalheObraDownload.do?select_action=&co_obra=17394&co_midia=2', NULL),
(4, 'Poema da Virgem Maria', 'Padre José de Anchieta', 'Quinhentismo', '../obras/capas/poema da bem-aventurada virgem maria, mãe de deus.png', 'Poema da Bem-aventurada Virgem Maria Mãe de Deus é uma obra escrita por São José de Anchieta, em 1563, durante o tempo em que ele esteve prisioneiro dos índios tamoios, no litoral norte de São Paulo. A obra é considerada um dos primeiros textos literários do Brasil, um dos clássicos da nossa literatura e também da Mariologia.', 'http://www.dominiopublico.gov.br/pesquisa/DetalheObraDownload.do?select_action=&co_obra=17395&co_midia=2', NULL),
(5, 'Auto da festa de São Lourenço', 'Padre José de Anchieta', 'Quinhentismo', '../obras/capas/auto da festa de sao lourenco.png', 'Este texto teatral foi concebido conforme os preceitos da Contrarreforma, isto é, de popularizar as artes para a difusão da fé católica, em um compromisso de fins puramente catequéticos. São representados temas bíblicos e o conflito entre o bem e o mal, ou seja, a queda e a redenção da humanidade, tidos como princípios universais.', 'http://www.dominiopublico.gov.br/pesquisa/DetalheObraDownload.do?select_action=&co_obra=1853&co_midia=2', NULL),
(6, 'Na Aldeia de Guaraparim', 'Padre José de Anchieta', 'Quinhentismo', '../obras/capas/na aldeia de guaraparim.png', 'Na aldeia de Guaraparim (1585) é uma obra de São José de Anchieta, escrita durante sua missão no Brasil colonial. O livro descreve a convivência entre os jesuítas e os indígenas da aldeia de Guaraparim, no Espírito Santo. Anchieta relata o cotidiano da aldeia, os esforços de evangelização dos nativos e os desafios culturais enfrentados pelos missionários. A obra reflete a tentativa de promover uma convivência pacífica entre indígenas e colonizadores, destacando a visão cristã de Anchieta sobre a relação entre os diferentes povos.', NULL, NULL),
(7, 'Arte de Gramática da Língua Tupi', 'Padre José de Anchieta', 'Quinhentismo', '../obras/capas/arte de gramatica da lingua mais usada na costa do brasil.png', 'Arte de Gramática da Língua Mais Usada na Costa do Brasil (1595) é uma obra de São José de Anchieta que sistematiza a língua Tupi, amplamente falada pelos indígenas da costa brasileira. A gramática detalha a fonologia, morfologia, sintaxe e vocabulário do Tupi, ajudando os missionários jesuítas a se comunicarem com os nativos e facilitando a evangelização. A obra é um importante marco para a história da linguística no Brasil e reflete os esforços de Anchieta para promover a integração entre indígenas e colonizadores por meio da língua.', NULL, NULL),
(8, 'Prosopopeia', 'Bento Teixeira', 'Barroco', '../obras/capas/prosopopeia.png', 'é uma obra épica escrita por Bento Teixeira, considerada uma das primeiras manifestações da literatura barroca no Brasil. O poema exalta a fundação da cidade de São Luís, no Maranhão, e a figura do governador Daniel de La Touche, responsável pela colonização da região. A obra mistura elementos da mitologia clássica com a narrativa histórica, buscando glorificar a colonização portuguesa no Brasil. Com seu estilo barroco, o poema enfatiza temas como a grandeza, a moralidade e a religiosidade, características marcantes desse período literário. Prosopopéia é um exemplo da literatura colonial que busca legitimar e celebrar o processo de colonização, ao mesmo tempo em que reflete as tensões e desafios dessa época. A obra é um marco na história da literatura brasileira e na introdução do barroco no país.', 'http://www.dominiopublico.gov.br/pesquisa/DetalheObraDownload.do?select_action=&co_obra=16579&co_midia=2', NULL),
(9, 'Poemas escolhidos', 'Gregório de Matos', 'Barroco', '../obras/capas/poemas escolhidos.png', 'Poemas Escolhidos de Gregório de Matos é uma seleção das principais poesias do poeta barroco brasileiro, conhecido por sua irreverência e crítica feroz à sociedade colonial. A obra reúne sonetos, sátiras, elegias e carmina que abordam temas como a corrupção política, os vícios da elite, a hipocrisia religiosa e as complexidades da vida cotidiana. Com uma linguagem marcada pela ironia, sarcasmo e uma forte dose de provocação, Gregório de Matos se destaca por suas críticas ácidas à moralidade de sua época, desafiando os padrões estabelecidos pela Igreja e pelas autoridades coloniais. Com um estilo literário de grande vigor, suas poesias continuam a ser um reflexo profundo das contradições e tensões do Brasil colonial, revelando um autor cuja obra ultrapassa o seu tempo e permanece relevante até os dias de hoje.  \n\n', 'http://www.dominiopublico.gov.br/pesquisa/DetalheObraDownload.do?select_action=&co_obra=16658&co_midia=2', NULL),
(10, 'Vila Rica', 'Cláudio Manuel da Costa', 'Arcadismo', '../obras/capas/vila rica.png', 'Publicado em 1773, Vila Rica é um poema épico que exalta a fundação e a importância da cidade de Vila Rica (atual Ouro Preto), centro econômico do ciclo do ouro no Brasil colonial. A obra mistura elementos históricos, como os bandeirantes e a exploração das minas, com alusões mitológicas, ressaltando a grandiosidade e o progresso. Além disso, o poema apresenta reflexões sutis sobre os conflitos sociais e políticos da época, especialmente os ideais iluministas que influenciaram a Inconfidência Mineira, movimento revolucionário do qual o próprio autor participou.', 'http://www.dominiopublico.gov.br/pesquisa/DetalheObraDownload.do?select_action=&co_obra=16557&co_midia=2', NULL),
(11, 'Culto Métrico', 'Cláudio Manuel da Costa', 'Arcadismo', '../obras/capas/culto metrico.png', 'Publicada em 1749, Culto Métrico é uma coletânea de poemas escritos durante o período em que Cláudio Manuel da Costa estudava em Portugal. A obra é fortemente influenciada pelo Arcadismo europeu e valoriza o rigor métrico, a simplicidade formal e a busca pela harmonia. Seus poemas têm como temas principais a natureza idealizada, a vida pastoral e a moderação dos sentimentos, características típicas do movimento árcade que buscava renovar a poesia brasileira com inspiração clássica.', 'http://www.dominiopublico.gov.br/pesquisa/DetalheObraDownload.do?select_action=&co_obra=16550&co_midia=2', NULL),
(12, 'Labirinto de Amor', 'Cláudio Manuel da Costa', 'Arcadismo', '../obras/capas/labirinto de amor.png', 'Publicado em 1753, Labirinto de Amor é um poema lírico que explora os conflitos e dilemas do amor não correspondido, muito presente na tradição árcade. A obra utiliza metáforas clássicas e uma linguagem refinada para expressar o embate entre a razão e a paixão, demonstrando a busca do poeta pelo equilíbrio e controle das emoções, que são elementos centrais da estética neoclássica e do Arcadismo.', NULL, NULL),
(13, 'Epicédio', 'Cláudio Manuel da Costa', 'Arcadismo', '../obras/capas/epicedio.png', 'Também publicado em 1753, o Epicídio é um poema fúnebre que homenageia a morte de uma pessoa estimada, exaltando suas virtudes e qualidades morais. Com tom solene e respeitoso, o poema segue a tradição clássica dos epicedion, mostrando a técnica apurada de Cláudio Manuel da Costa em termos de', 'http://www.dominiopublico.gov.br/pesquisa/DetalheObraDownload.do?select_action=&co_obra=16551&co_midia=2', NULL),
(14, 'Obras Poéticas', 'Cláudio Manuel da Costa', 'Arcadismo', '../obras/capas/obras poeticas.png', 'A coletânea Obras Poéticas, publicada em 1768, reúne os principais poemas de Cláudio Manuel da Costa e representa o auge de sua produção literária. Nela, o autor consolida sua voz no Arcadismo brasileiro, explorando temas variados, como a exaltação da natureza, a vida bucólica, o amor e até críticas sociais sutis. A obra reflete sua maturidade artística, marcada pela busca da simplicidade formal, do equilíbrio e da métrica correta, características que definem o neoclassicismo e o espírito árcade.', 'http://www.dominiopublico.gov.br/pesquisa/DetalheObraDownload.do?select_action=&co_obra=16554&co_midia=2', NULL),
(15, 'Pro Anima Studiorum Instauratione Oratio', 'Santa Rita Durão', 'Arcadismo', '../obras/capas/pro anima studiorum instauratione oratio.png', 'Publicado em 1778, o discurso de Frei José de Santa Rita Durão defende a necessidade urgente de renovar o sistema educacional no Brasil colonial. O autor enfatiza que o desenvolvimento intelectual e moral da sociedade depende de uma educação que estimule o pensamento crítico e o conhecimento científico. Ele critica os métodos tradicionais, considerados ultrapassados, e propõe uma reforma que valorize a pesquisa e o ensino voltado para a formação integral dos estudantes. A obra reflete os ideais iluministas e o desejo de progresso cultural no Brasil da época.', 'http://www.dominiopublico.gov.br/pesquisa/DetalheObraDownload.do?select_action=&co_obra=16642&co_midia=2', NULL),
(16, 'Caramuru', 'Santa Rita Durão', 'Arcadismo', '../obras/capas/caramuru.png', 'Publicado em 1781, o poema épico Caramuru, de Frei José de Santa Rita Durão, narra a trajetória de Diogo Álvares Correia, um português que naufragou na costa brasileira e passou a viver entre os indígenas tupinambás. A obra mistura elementos históricos e lendários para destacar a relação de convivência entre europeus e indígenas, ressaltando a importância do diálogo e da adaptação cultural. Além disso, o poema exalta a exuberância da natureza brasileira e reflete sobre a formação da identidade nacional, construída a partir da união e dos conflitos entre diferentes culturas.', NULL, NULL),
(17, 'Uruguai', 'Basílio da Gama', 'Arcadismo', '../obras/capas/uruguai.png', 'Publicado em 1769, Uruguai é um poema épico que narra a expedição conjunta de portugueses e espanhóis contra as missões jesuíticas no sul do Brasil, no Rio Grande do Sul. A obra retrata a luta pelo domínio da região, combinando fatos históricos com elementos mitológicos. Basílio da Gama critica os jesuítas, acusando-os de manipulação, e exalta as políticas do ministro Pombal, que buscava o controle e a organização das colônias. O poema também destaca a bravura e a resistência dos indígenas, além de exaltar a natureza exuberante do Brasil, contribuindo para a formação da identidade nacional colonial.', NULL, NULL),
(18, 'Epitalâmio às Núpcias da Sra. D. Maria Amália', 'Basílio da Gama', 'Arcadismo', '../obras/capas/epitalamio as nupcias da sra. d. maria amalia.png', 'Escrito e publicado em 1769, este poema celebra o casamento da filha do ministro Pombal, D. Maria Amália. Além de uma homenagem à união matrimonial, o poema teve um papel decisivo na vida de Basílio da Gama, pois foi com ele que o poeta conquistou o perdão e a proteção de Pombal, que havia condenado-o ao degredo por suspeita de ligação com os jesuítas. A obra exalta valores como a união familiar, a estabilidade social e a importância da corte portuguesa.', NULL, NULL),
(19, 'Quitúbia', 'Basílio da Gama', 'Arcadismo', '../obras/capas/quitubia.png', 'Publicado em 1791, Quitúbia é um poema que revela uma visão mais pessoal e reflexiva do autor, abordando temas como a morte, o destino e a passagem do tempo. Diferente de suas obras anteriores, que tinham forte cunho político e histórico, este poema apresenta um tom mais filosófico e introspectivo, demonstrando a maturidade do poeta ao lidar com questões existenciais e espirituais.', NULL, NULL),
(20, 'Ode a D. José', 'Basílio da Gama', 'Arcadismo', '../obras/capas/ode a d. jose.png', 'Publicado em 1765, este poema é uma celebração ao rei D. José I de Portugal, destacando suas qualidades como governante e sua importância para o país. A obra está alinhada com o pensamento do absolutismo ilustrado, valorizando o poder do monarca e seu papel na manutenção da ordem e do progresso em Portugal e nas colônias.', NULL, NULL),
(21, 'Ode ao Conde da Cunha', 'Basílio da Gama', 'Arcadismo', '../obras/capas/ode ao conde da cunha.png', 'Publicado em 1769, o poema é uma homenagem ao Conde da Cunha, importante figura política e aliado do ministro Pombal. Nele, Basílio da Gama exalta as virtudes, méritos e feitos do conde, reforçando seu apoio às políticas reformistas e centralizadoras promovidas por Pombal. A obra reflete o compromisso do poeta com as mudanças políticas e sociais da época.', NULL, NULL),
(22, 'Marília de Dirceu', 'Tomás Antônio Gonzaga', 'Arcadismo', '../obras/capas/marilia de dirceu.png', 'Marília de Dirceu é a obra mais conhecida de Tomás Antônio Gonzaga, publicada em 1792. Trata-se de uma coletânea de poesias líricas, nas quais o autor expressa seu amor idealizado por Maria Dorotéia, sua musa e noiva. A obra segue os preceitos do Arcadismo, com uma forte influência das ideias neoclássicas de simplicidade e valorização da natureza. Além de exaltar o amor pastoral e idealizado, Marília de Dirceu reflete o contexto social e político da época, especialmente as tensões que levariam à Inconfidência Mineira, movimento do qual Gonzaga foi acusado de participar. A obra também é uma crítica sutil ao domínio português no Brasil e aos costumes da época, mantendo, no entanto, a forma e os temas da poesia clássica.', 'http://www.dominiopublico.gov.br/pesquisa/DetalheObraDownload.do?select_action=&co_obra=17456&co_midia=2', NULL),
(23, 'Cartas Chilenas', 'Tomás Antônio Gonzaga', 'Arcadismo', '../obras/capas/cartas chilenas.png', 'Publicado postumamente em 1863, Cartas Chilenas é uma sátira política escrita por Tomás Antônio Gonzaga, que se inspira nos eventos da década de 1780 em Minas Gerais. A obra é composta por uma série de cartas fictícias enviadas de \"um chileno\" para \"um amigo\" em Portugal. Através dessas cartas, Gonzaga critica o governo de D. Luís da Cunha Meneses, governador de Minas Gerais, e expõe os problemas de administração, a corrupção e as injustiças que marcaram a gestão portuguesa no Brasil. Embora a obra tenha sido publicada anos depois de sua prisão e exílio, ela reflete a oposição de Gonzaga ao governo colonial e é uma das primeiras expressões de crítica política bem elaborada na literatura brasileira. A sátira é uma das mais importantes manifestações literárias do período colonial.', 'http://www.dominiopublico.gov.br/pesquisa/DetalheObraDownload.do?select_action=&co_obra=17453&co_midia=2', NULL),
(24, 'Tratado de Direito Natural', 'Tomás Antônio Gonzaga', 'Arcadismo', '../obras/capas/tratado de direito natural.png', 'O Tratado de Direito Natural (1768) é uma obra de caráter jurídico e filosófico escrita por Tomás Antônio Gonzaga, com foco na teoria do Direito Natural. A obra reflete as influências do Iluminismo e busca defender a ideia de que os direitos do ser humano são universais e imutáveis, baseados na razão e na natureza humana. A obra é importante para entender o pensamento jurídico de Gonzaga, e também seu envolvimento com as ideias iluministas que estavam ganhando força na Europa no século XVIII. Embora o Tratado de Direito Natural não seja tão conhecido quanto sua produção literária, ele revela a formação intelectual do autor e sua capacidade de transitar entre as esferas jurídica e literária.', NULL, NULL),
(25, 'A Conceição', 'Tomás Antônio Gonzaga', 'Arcadismo', '../obras/capas/a conceicao.png', 'A Conceição (1802) é uma obra religiosa de Tomás Antônio Gonzaga que reflete sua devoção à Virgem Maria. Nela, Gonzaga descreve, por meio de versos líricos e inspirados pela tradição barroca, a imagem da Virgem Maria, exortando à pureza e à fé cristã. A obra é carregada de sentimentos devocionais e de uma profunda adoração, representando uma fase mais madura e introspectiva do autor, especialmente em comparação com as poesias românticas e passionais de Marília de Dirceu. A Conceição também é um reflexo da influência da religiosidade popular e da literatura sacra da época, além de apresentar uma escrita mais melancólica e contemplativa, em contraponto aos temas mais focados na crítica social e política de suas outras obras.', NULL, NULL),
(26, 'Canção do exílio', 'Antônio Gonçalves Dias', 'Romantismo', '../obras/capas/cancao do exilio.png', 'Escrito em 1843, durante os estudos do autor em Coimbra, o poema expressa a saudade do Brasil sentida por um eu lírico exilado. Compara de forma idealizada a natureza e a vida brasileira com a realidade estrangeira. \nA natureza tropical surge como símbolo da pátria perfeita e perdida. \nEsse sentimento patriótico tornou-se um dos marcos do Romantismo brasileiro. \nÉ um dos poemas mais conhecidos da literatura brasileira e símbolo do nacionalismo.', 'http://www.dominiopublico.gov.br/pesquisa/DetalheObraDownload.do?select_action=&co_obra=2112&co_midia=2', NULL),
(27, 'I-Juca-Pirama', 'Antônio Gonçalves Dias', 'Romantismo', '../obras/capas/i-juca-pirama.png', 'Publicado em 1851, o poema narra a história de um guerreiro tupi capturado, libertado para ver o pai e, depois, desonrado por ele por ter pedido clemência. \nO filho luta para provar sua bravura e recuperar a honra aos olhos do pai. \nA obra traz temas como coragem, sacrifício, honra e valores indígenas. \nPossui estrutura épica, com forte apelo emocional e dramatização da cultura nativa.', 'http://www.dominiopublico.gov.br/pesquisa/DetalheObraDownload.do?select_action=&co_obra=16652&co_midia=2', NULL),
(28, 'Canto do guerreiro', 'Antônio Gonçalves Dias', 'Romantismo', '../obras/capas/canto do guerreiro.png', 'Publicado nos Primeiros Cantos (1846), o poema mostra um guerreiro indígena exaltando sua força e coragem diante da morte. \nEle aceita o fim com bravura, representando o ideal de herói romântico. \nA obra expressa os valores indígenas idealizados: liberdade, coragem e fidelidade à tribo.\nReforça o romantismo heroico e a exaltação do indígena como símbolo nacional.', NULL, NULL),
(29, 'Marabá', 'Antônio Gonçalves Dias', 'Romantismo', '../obras/capas/maraba.png', 'Publicado também em Primeiros Cantos (1846), “Marabá” retrata o sofrimento de uma jovem mestiça rejeitada por ser filha de branco com índia. \nEla vive o conflito de identidade, sem aceitação em nenhuma das culturas. \nO poema denuncia o preconceito racial e a exclusão social no Brasil colonial. \nA personagem representa o drama da mestiçagem e da formação do povo brasileiro.', NULL, NULL),
(30, 'Canto do tamoio', 'Antônio Gonçalves Dias', 'Romantismo', '../obras/capas/canto do tamoio.png', 'Publicado em Segundos Cantos (1847), o poema apresenta um velho guerreiro tamoio incitando os jovens da tribo a resistirem à dominação dos colonizadores. Ele valoriza a liberdade acima da vida, recusando a submissão. \nA obra destaca o orgulho indígena e critica a perda da cultura nativa. \nÉ uma exaltação da resistência e da dignidade dos povos originários.', 'http://www.dominiopublico.gov.br/pesquisa/DetalheObraDownload.do?select_action=&co_obra=200085&co_midia=2', NULL),
(31, 'O Guarani', 'Jóse de Alencar', 'Romantismo', '../obras/capas/o guarani.png', 'Publicado em 1857, é um romance indianista que conta a história do amor entre Peri, um índio corajoso e leal, e Cecília, filha de um fidalgo português. Passado no Brasil colonial, o livro mistura aventura, romance e conflitos entre indígenas e colonizadores. A obra destaca a coragem e a nobreza do personagem indígena, símbolo da formação do povo brasileiro. É um marco do Indianismo e da literatura nacional. Além disso, aborda o confronto entre culturas e a idealização do indígena como herói romântico. A narrativa tem ritmo ágil e cenas emocionantes de ação e drama, o que conquistou muitos leitores.', 'http://www.dominiopublico.gov.br/pesquisa/DetalheObraDownload.do?select_action=&co_obra=1843&co_midia=2', NULL),
(32, 'Iracema', 'Jóse de Alencar', 'Romantismo', '../obras/capas/iracema.png', 'Publicado em 1865, este romance narra o romance entre Iracema, uma índia da tribo tabajara, e Martim, um colonizador português. Iracema é vista como a “mãe do Brasil”, representando a origem da nação brasileira pela fusão do indígena com o europeu. O livro explora temas como amor, sacrifício, cultura indígena e o nascimento do Brasil. É uma obra poética e simbólica, muito valorizada no Romantismo brasileiro. A linguagem é rica e cheia de metáforas, evocando a natureza exuberante do Brasil. A trama também reflete sobre a perda e a transformação cultural causada pela colonização.', 'http://www.dominiopublico.gov.br/pesquisa/DetalheObraDownload.do?select_action=&co_obra=1844&co_midia=2', NULL),
(33, 'Ubirajara', 'Jóse de Alencar', 'Romantismo', '../obras/capas/ubirajara.png', 'Publicado em 1874, este romance apresenta a vida de Ubirajara, um jovem guerreiro tupi, e suas aventuras e feitos heroicos. A obra exalta a cultura, os costumes e a coragem dos indígenas brasileiros. Focado na tradição oral e nos mitos indígenas, o livro reforça a importância da identidade nacional e do respeito à ancestralidade indígena. Ubirajara é retratado como um líder ideal, valente e justo, símbolo da bravura e da pureza da cultura indígena. A narrativa valoriza a ligação do homem com a natureza e os valores de honra e lealdade.', 'http://www.dominiopublico.gov.br/pesquisa/DetalheObraDownload.do?select_action=&co_obra=16679&co_midia=2', NULL),
(34, 'Senhora', 'Jóse de Alencar', 'Romantismo', '../obras/capas/senhora.png', 'Publicado em 1875, este romance urbano narra a história de Aurélia Camargo, uma jovem que, após receber uma grande herança, usa seu poder financeiro para conquistar Fernando Seixas, um homem que a havia rejeitado quando ela era pobre. A obra trata de temas como sociedade, casamento por interesse, orgulho, vingança e transformação social. É um retrato das relações amorosas e das questões sociais do Brasil do século XIX. Aurélia representa a mulher forte e decidida, que desafia as convenções sociais da época. O romance também discute as desigualdades econômicas e os valores materialistas da sociedade.', 'http://www.dominiopublico.gov.br/pesquisa/DetalheObraDownload.do?select_action=&co_obra=1847&co_midia=2', NULL),
(35, 'Lucíola', 'Jóse de Alencar', 'Romantismo', '../obras/capas/luciola.png', 'Publicado em 1862, o romance acompanha a vida de Lúcia, uma cortesã carioca que vive um drama de amor e redenção ao se apaixonar por Paulo, um homem da alta sociedade. A obra discute questões morais, preconceito social, perdão e a possibilidade de transformação pessoal. Retrata a hipocrisia da sociedade e os conflitos internos dos personagens. Lucíola busca superar seu passado e provar seu valor, enfrentando o julgamento dos outros. A narrativa é marcada pelo tom crítico e pela análise das relações humanas em um contexto de moralidade rígida.', 'http://www.dominiopublico.gov.br/pesquisa/DetalheObraDownload.do?select_action=&co_obra=1845&co_midia=2', NULL),
(37, 'Lira dos Vinte Anos', 'Manuel Antônio Álvares de Azevedo', 'Romantismo', '../obras/capas/lira dos vinte anos.png', 'Publicada em 1853, de forma póstuma, é uma coletânea de poemas que expressa os sentimentos intensos da juventude, marcada por dualidade emocional: de um lado, a idealização do amor e da morte; de outro, o sarcasmo e o erotismo. A obra é dividida em duas partes: uma sentimental e melancólica, outra irônica e sombria. A linguagem é rica em imagens dramáticas e temas como solidão, tédio, amor platônico e morbidez. É um marco do ultrarromantismo brasileiro, refletindo os conflitos internos do autor. A presença da morte como alívio para o sofrimento é constante. A obra mostra o contraste entre sonho e realidade, ideal e frustração.', 'http://www.dominiopublico.gov.br/pesquisa/DetalheObraDownload.do?select_action=&co_obra=16539&co_midia=2', NULL),
(38, 'A Noite na Taverna', 'Manuel Antônio Álvares de Azevedo', 'Romantismo', '../obras/capas/a noite na taverna.png', 'Publicada em 1855, também de forma póstuma, essa obra reúne contos interligados narrados por jovens boêmios em uma taverna, cheios de histórias de decadência, loucura, violência e morte. Cada personagem revela experiências marcadas por crimes, amores trágicos e elementos fantásticos. A atmosfera é sombria e decadente, com forte influência do romantismo gótico europeu. A linguagem é intensa, carregada de pessimismo e exagero. Os contos revelam uma visão niilista da vida, sem esperança ou redenção. É uma obra que representa o lado mais extremo do ultrarromantismo.', 'http://www.dominiopublico.gov.br/pesquisa/DetalheObraDownload.do?select_action=&co_obra=16541&co_midia=2', NULL),
(39, 'Macário', 'Manuel Antônio Álvares de Azevedo', 'Romantismo', '../obras/capas/macario.png', 'Publicada postumamente em 1855, essa peça teatral dividida em dois atos apresenta o jovem Macário em diálogo com o Diabo sobre os valores da vida, religião e sociedade. A trama se passa em uma viagem e numa festa, onde Macário se depara com a falsidade do mundo. A obra mistura crítica social, existencialismo e ironia, com influências de Goethe e Byron. Questiona a hipocrisia da moral burguesa e a busca por sentido na vida. O Diabo funciona como símbolo da razão e do ceticismo. A peça propõe reflexões sobre liberdade, desejo e frustração.', 'http://www.dominiopublico.gov.br/pesquisa/DetalheObraDownload.do?select_action=&co_obra=16540&co_midia=2', NULL),
(40, 'O Poema do Frade', 'Manuel Antônio Álvares de Azevedo', 'Romantismo', '../obras/capas/o poema do frade.png', 'Publicado em edições póstumas no final do século XIX, é um poema narrativo sobre um frade que abandona a vida religiosa ao se apaixonar, entrando em conflito com os valores morais e espirituais. A narrativa mescla lirismo com ironia e crítica à repressão sexual. Mostra o embate entre fé e desejo, religiosidade e liberdade. A linguagem é provocativa, com cenas de intensidade emocional e questionamento ético. Azevedo expõe a hipocrisia da vida monástica e a tensão entre corpo e espírito. É um exemplo claro da visão crítica do autor sobre a moral tradicional. \n\n', 'http://www.dominiopublico.gov.br/pesquisa/DetalheObraDownload.do?select_action=&co_obra=16542&co_midia=2', NULL),
(41, 'O Conde Lopo', 'Manuel Antônio Álvares de Azevedo', 'Romantismo', '../obras/capas/o conde lopo.png', 'Também publicado em edições póstumas no século XIX, é um poema narrativo com tom sombrio e fantástico que conta a história do atormentado Conde Lopo, envolvido em um amor trágico com elementos sobrenaturais. A ambientação é gótica, cheia de mistério, morte e solidão. A narrativa revela o sofrimento do protagonista diante de uma paixão impossível. O amor é retratado como força destrutiva e obsessiva. A linguagem é simbólica e intensa, revelando angústia existencial. A obra critica os excessos do ideal romântico e mostra a fragilidade emocional do ser humano.', NULL, NULL),
(42, 'As Primaveras', 'Casimiro de Abreu', 'Romantismo', '../obras/capas/as primaveras.png', 'É a única coletânea de poemas publicada por Casimiro de Abreu em vida, em 1859. A obra reúne textos líricos que exploram temas como a infância idealizada, o amor puro e ingênuo, a natureza, a religiosidade, o nacionalismo e a nostalgia. A linguagem é simples, musical e carregada de emoção. Os versos mostram uma alma sonhadora, que busca refúgio na memória e na beleza do passado. O livro representa bem o espírito jovem e sentimental da segunda geração romântica. É frequentemente explorado nos vestibulares por seu tom suave e por refletir valores do Romantismo no Brasil imperial.', 'http://www.dominiopublico.gov.br/pesquisa/DetalheObraDownload.do?select_action=&co_obra=2173&co_midia=2', NULL),
(43, 'Meus Oito Anos', 'Casimiro de Abreu', 'Romantismo', '../obras/capas/meus oito anos.png', 'Poema mais conhecido de Casimiro, foi publicado em 1859 na coletânea As Primaveras. Nele, o eu lírico relembra a infância com ternura e saudade, valorizando a liberdade, o amor familiar e a simplicidade da vida no campo. A musicalidade reforça o tom emotivo e nostálgico. O poema também simboliza a perda da inocência e a aproximação da morte, tema constante no Romantismo. É muito utilizado em vestibulares por expressar claramente o saudosismo romântico. A idealização da infância o torna um dos poemas mais representativos do autor.', 'http://www.dominiopublico.gov.br/pesquisa/DetalheObraDownload.do?select_action=&co_obra=86500&co_midia=2', NULL),
(44, 'O Poeta e a Flor', 'Casimiro de Abreu', 'Romantismo', '../obras/capas/o poeta e a flor.png', 'Esse poema foi publicado em 1859, também como parte da coletânea As Primaveras. Nele, Casimiro compara o poeta a uma flor frágil, destacando a sensibilidade artística e a vulnerabilidade diante do mundo real. A flor morre quando afastada da natureza; o poeta, quando afastado do sonho. A obra carrega um tom de melancolia e reflexão, com imagens delicadas e suaves. É muito cobrado em vestibulares por expressar a figura do poeta como ser idealista e incompreendido. Também reflete a tensão entre sonho e realidade, comum no Romantismo.', NULL, NULL),
(45, 'Canção do Exílio (versão de Casimiro)', 'Casimiro de Abreu', 'Romantismo', '../obras/capas/cancao do exilio (versao de casimiro).png', 'A versão de Casimiro da clássica Canção do Exílio foi publicada em 1859, em As Primaveras. Nela, o poeta reforça o tom pessoal e sentimental, expressando com suavidade a saudade da pátria e o amor pela natureza brasileira. \nComparada à versão de Gonçalves Dias, é mais intimista e lírica. A obra destaca o Brasil como espaço de lembrança afetiva. É um exemplo claro da sensibilidade lírica da segunda geração romântica. Muito usada em vestibulares por seu caráter intertextual e emocional.', 'http://www.dominiopublico.gov.br/pesquisa/DetalheObraDownload.do?select_action=&co_obra=86488&co_midia=2', NULL),
(46, 'Lembrança de Morrer', 'Casimiro de Abreu', 'Romantismo', '../obras/capas/lembranca de morrer.png', 'Publicado em 1859, no livro As Primaveras, esse poema expressam o pressentimento da morte de maneira serena e resignada. O eu lírico aceita o fim com doçura e melancolia, sem revolta. A linguagem simples reforça o tom contemplativo, típico da poesia romântica. O poema reflete a visão do morrer como retorno à natureza e libertação da alma sonhadora. Representa a juventude marcada pela fragilidade da existência, característica da vida e obra de Casimiro. \n\n', 'http://www.dominiopublico.gov.br/pesquisa/DetalheObraDownload.do?select_action=&co_obra=86444&co_midia=2', NULL),
(47, 'Espumas Flutuantes', 'Antônio Frederico de Castro Alves', 'Romantismo', '../obras/capas/espumas flutuantes.png', 'Publicada em 1870, foi a única obra lançada por Castro Alves em vida. Reúne poemas que misturam o lirismo amoroso com o engajamento social, marcando a transição entre a poesia íntima e a combativa. Com uma linguagem exaltada e musical, trata de temas como paixão, saudade, liberdade e justiça. A obra apresenta o estilo vibrante do autor e revela sua maturidade poética, consolidando-o como grande nome da terceira geração romântica, também conhecida como Romantismo condoreiro.', 'http://www.dominiopublico.gov.br/pesquisa/DetalheObraDownload.do?select_action=&co_obra=16590&co_midia=2', NULL),
(48, 'O Navio Negreiro', 'Antônio Frederico de Castro Alves', 'Romantismo', '../obras/capas/o navio negreiro.png', 'Publicado postumamente em 1880, é o poema mais famoso de Castro Alves e símbolo da luta contra a escravidão. Com imagens impactantes e linguagem oratória, descreve os horrores da travessia dos africanos escravizados no Atlântico. É uma obra central do Romantismo social brasileiro, marcada pela denúncia, emoção intensa e apelo à liberdade. Frequentemente cobrado em vestibulares por seu valor histórico, literário e humanitário.', 'http://www.dominiopublico.gov.br/pesquisa/DetalheObraDownload.do?select_action=&co_obra=16591&co_midia=2', NULL),
(49, 'Vozes d’África', 'Antônio Frederico de Castro Alves', 'Romantismo', '../obras/capas/vozes d’africa.png', 'Também publicado postumamente em 1880, esse poema retrata a África como uma entidade personificada, que clama por justiça diante do sofrimento causado pela escravidão. É um grito poético contra o colonialismo e a opressão. Com tom épico e linguagem elevada, expressa a solidariedade humana e o ideal de liberdade. Muito cobrado por seu valor simbólico e pela presença marcante do discurso social e político na literatura.', 'http://www.dominiopublico.gov.br/pesquisa/DetalheObraDownload.do?select_action=&co_obra=16725&co_midia=2', NULL),
(50, 'A Cachoeira de Paulo Afonso', 'Antônio Frederico de Castro Alves', 'Romantismo', '../obras/capas/a cachoeira de paulo afonso.png', 'Publicado postumamente em 1876, é um poema narrativo que mistura paisagem natural grandiosa, drama humano e reflexão social. A cachoeira funciona como cenário para uma história de amor, sofrimento e libertação. A obra faz parte do projeto inacabado Os Escravos e é lembrada pela fusão entre lirismo, crítica social e exuberância descritiva. Cobrada por mostrar o equilíbrio entre beleza poética e denúncia.', 'http://www.dominiopublico.gov.br/pesquisa/DetalheObraDownload.do?select_action=&co_obra=35994&co_midia=2', NULL),
(51, 'Os Escravos', 'Antônio Frederico de Castro Alves', 'Romantismo', '../obras/capas/os escravos.png', 'Publicado postumamente em 1883, é uma coletânea que reúne os poemas abolicionistas de Castro Alves. Representa o ápice de sua poesia social, voltada à defesa da liberdade, dignidade e justiça para os escravizados. A obra é marcada por forte carga emocional, linguagem grandiosa e espírito revolucionário. É muito citada em vestibulares como símbolo do engajamento literário no século XIX, com destaque para o autor como o “poeta dos escravos”.', 'http://www.dominiopublico.gov.br/pesquisa/DetalheObraDownload.do?select_action=&co_obra=16727&co_midia=2', NULL);




